head.b:skin:
/* =====================================
   GLOBAL / SHARED STYLES
===================================== */
:root{
  --tcn-primary:#0b5bb5;
  --tcn-primary-dark:#073f80;
  --tcn-secondary:#f59e0b;
  --tcn-text:#172033;
  --tcn-muted:#667085;
  --tcn-soft:#f4f8fd;
  --tcn-border:#e5eaf1;
  --tcn-white:#fff;
  --tcn-shadow:0 14px 38px rgba(9,53,102,.12);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
html.tcn-form-return{scroll-behavior:auto!important}
body{margin:0;font-family:Arial,Helvetica,sans-serif;color:var(--tcn-text);background:#fff;line-height:1.65}
a{color:var(--tcn-primary);text-decoration:none}
img{max-width:100%;height:auto}
.container{width:min(1180px,calc(100% - 36px));margin:auto}
/* Shared section helpers */
.section{padding:82px 0}
.section-soft{background:var(--tcn-soft)}
.section-heading{text-align:center;max-width:760px;margin:0 auto 42px}
.section-heading>span,.eyebrow{display:inline-block;font-size:12px;font-weight:800;letter-spacing:1.8px;color:var(--tcn-secondary)}
.section-heading h2{font-size:38px;line-height:1.2;margin:10px 0 14px}
.section-heading p{color:var(--tcn-muted);margin:0}
.section-heading.light p{color:#dbeafe}
.cards{display:grid;gap:24px}
.cards-3{grid-template-columns:repeat(3,1fr)}
/* Shared buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:0 24px;border:0;border-radius:8px;font-size:13px;font-weight:800;letter-spacing:.3px;cursor:pointer}
.btn-primary{background:var(--tcn-primary);color:#fff}
.btn-secondary{background:var(--tcn-secondary);color:#172033}
.btn-light{background:#fff;color:var(--tcn-primary)}
.btn-block{width:100%}
/* Shared form controls */
input,select,textarea{width:100%;margin-top:7px;border:1px solid #d7deea;border-radius:8px;padding:13px 14px;font:inherit;background:#fff}
input:focus,select:focus,textarea:focus{outline:2px solid rgba(11,91,181,.16);border-color:var(--tcn-primary)}
/* Footer + content pages */
.site-footer{background:#0e1728;color:#cbd5e1;padding:55px 0 0}
.footer-grid{display:grid;grid-template-columns:1.3fr 1fr .7fr;gap:50px}
.footer-grid h4{color:#fff;margin-top:0}
.footer-brand{font-weight:900;color:#fff;font-size:20px}
.footer-menu{list-style:none;padding:0;margin:0}
.footer-menu a{color:#cbd5e1}
.footer-bottom{border-top:1px solid rgba(255,255,255,.1);margin-top:36px;padding:20px 0;font-size:13px}
.content-area{max-width:900px}
.post-card{padding:24px 0;border-bottom:1px solid var(--tcn-border)}
.entry-content{font-size:17px}
.entry-content h2,.entry-content h3{line-height:1.25}
.single-thumb{border-radius:14px;margin-bottom:25px}
@media(max-width:980px){
  .cards-3{grid-template-columns:1fr 1fr}
}
@media(max-width:680px){
  .section{padding:58px 0}
  .section-heading h2{font-size:30px}
  .cards-3,.footer-grid{grid-template-columns:1fr}
}
/* ========================================
   HEADER - TAI CHINH NHANH
======================================== */
.tcn-header{
  position:relative;
  z-index:999;
  width:100%;
  height:96px;
  background:#063b7d;
  border-bottom:0;
}
/* ========================================
   CONTAINER
======================================== */
.tcn-header-container{
  width:min(1480px,calc(100% - 56px));
  height:96px;
  margin:0 auto;
  display:grid;
  grid-template-columns:260px 1fr 230px;
  align-items:center;
  gap:24px;
}
/* ========================================
   LOGO
======================================== */
.tcn-logo{
  height:96px;
  display:flex;
  align-items:center;
  overflow:visible;
}
.tcn-logo > a{
  display:flex;
  align-items:center;
  height:100%;
  line-height:0;
}
.tcn-logo-image{
  display:block;
  width:220px;
  height:76px;
  max-width:220px;
  max-height:76px;
  object-fit:contain;
  object-position:left center;
  margin:0;
}
/* ========================================
   NAVIGATION
======================================== */
.tcn-navigation{
  min-width:0;
  display:flex;
  align-items:center;
  justify-content:center;
}
.tcn-menu{
  list-style:none;
  margin:0;
  padding:0;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:36px;
}
.tcn-menu li{
  position:relative;
  margin:0;
  padding:0;
}
/* MENU */
.tcn-menu li a{
  position:relative;
  display:inline-flex;
  align-items:center;
  min-height:96px;
  color:#fff;
  font-size:17px;
  font-weight:700;
  line-height:1;
  text-transform:uppercase;
  white-space:nowrap;
  text-decoration:none;
  transition:
    color .2s ease,
    opacity .2s ease;
}
/* HOVER + ACTIVE */
.tcn-menu li a:hover,
.tcn-menu li a:focus,
.tcn-menu .current-menu-item > a,
.tcn-menu .current_page_item > a{
  color:#f5a000;
}
/* GẠCH VÀNG ACTIVE */
.tcn-menu .current-menu-item > a:after,
.tcn-menu .current_page_item > a:after{
  content:"";
  position:absolute;
  left:0;
  right:0;
  bottom:18px;
  height:2px;
  background:#f5a000;
}
/* ========================================
   HOTLINE
======================================== */
.tcn-hotline{
  display:flex;
  justify-content:flex-end;
  align-items:center;
}
.tcn-hotline a{
  min-height:48px;
  padding:0 22px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  background:transparent;
  color:#fff;
  border:1px solid rgba(255,255,255,.75);
  border-radius:999px;
  font-size:16px;
  font-weight:800;
  line-height:1;
  text-decoration:none;
  white-space:nowrap;
  transition:
    background .2s ease,
    border-color .2s ease;
}
.tcn-hotline a:hover,
.tcn-hotline a:focus{
  background:rgba(255,255,255,.10);
  border-color:#fff;
  color:#fff;
  transform:none;
}
.tcn-hotline-icon{
  font-size:18px;
  line-height:1;
}
/* ========================================
   MOBILE MENU BUTTON
======================================== */
.tcn-mobile-menu{
  display:none;
  width:40px;
  height:40px;
  padding:7px;
  border:0;
  background:transparent;
  cursor:pointer;
}
.tcn-mobile-menu span{
  display:block;
  width:100%;
  height:2px;
  margin:5px 0;
  background:#fff;
}
/* ========================================
   LAPTOP
======================================== */
@media(max-width:1250px){
  .tcn-header-container{
    width:calc(100% - 40px);
    grid-template-columns:210px 1fr 190px;
    gap:16px;
  }
  .tcn-logo-image{
    width:190px;
    max-width:190px;
  }
  .tcn-menu{
    gap:22px;
  }
  .tcn-menu li a{
    font-size:15px;
  }
  .tcn-hotline a{
    padding:0 15px;
    font-size:14px;
  }
}
/* ========================================
   TABLET / MOBILE NAVIGATION
======================================== */
@media(max-width:991px){
  .tcn-header,
  .tcn-header-container{
    height:76px;
  }
  .tcn-header-container{
    width:calc(100% - 32px);
    grid-template-columns:190px 1fr auto auto;
    padding:0;
    column-gap:12px;
  }
  .tcn-logo{
    height:76px;
  }
  .tcn-logo-image{
    width:180px;
    height:62px;
    max-width:180px;
    max-height:62px;
  }
  /* DROPDOWN MOBILE */
  .tcn-navigation{
    display:none;
    position:absolute;
    top:76px;
    left:0;
    right:0;
    background:#063b7d;
    border-top:1px solid rgba(255,255,255,.12);
    padding:14px 20px 22px;
    box-shadow:0 18px 30px rgba(0,28,65,.24);
  }
  .tcn-navigation.is-open{
    display:block;
  }
  .tcn-menu{
    flex-direction:column;
    align-items:flex-start;
    gap:0;
  }
  .tcn-menu li{
    width:100%;
  }
  .tcn-menu li a{
    width:100%;
    min-height:0;
    padding:14px 0;
    font-size:16px;
    line-height:1.3;
  }
  .tcn-menu .current-menu-item > a:after,
  .tcn-menu .current_page_item > a:after{
    display:none;
  }
  .tcn-hotline{
    grid-column:3;
  }
  .tcn-mobile-menu{
    display:block;
    grid-column:4;
  }
}
/* ========================================
   MOBILE
======================================== */
@media(max-width:575px){
  .tcn-header-container{
    grid-template-columns:155px 1fr auto auto;
    width:calc(100% - 24px);
  }
  .tcn-logo-image{
    width:150px;
    height:56px;
    max-width:150px;
    max-height:56px;
  }
  .tcn-hotline a{
    min-height:36px;
    padding:0 10px;
    font-size:12px;
  }
}
/* ========================================
   SMALL MOBILE
======================================== */
@media(max-width:440px){
  .tcn-hotline{
    display:none;
  }
  .tcn-header-container{
    grid-template-columns:155px 1fr auto;
  }
  .tcn-mobile-menu{
    grid-column:3;
  }
}
/* FOOTER LANDING - MATCH REFERENCE */
.tcn-footer{position:relative;overflow:hidden;padding-top:34px;background:radial-gradient(circle at 16% 0,rgba(18,104,220,.25),transparent 30%),linear-gradient(145deg,#05295b 0%,#073d7e 48%,#04244e 100%);color:#fff}
.tcn-footer:before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 78%,rgba(12,98,198,.18),transparent 45%),linear-gradient(115deg,transparent 30%,rgba(255,255,255,.025) 50%,transparent 68%)}
.tcn-footer-wrap{position:relative;z-index:2;max-width:1500px}
.tcn-footer-hero{display:grid;grid-template-columns:1.05fr 1.65fr 1.05fr;align-items:center;gap:45px;padding:37px 42px;border:1px solid rgba(255,255,255,.06);border-radius:22px;background:linear-gradient(110deg,rgba(10,73,157,.95),rgba(7,55,121,.92));box-shadow:0 20px 46px rgba(0,17,47,.2)}
.tcn-footer-hero-brand{padding-right:38px;border-right:1px solid rgba(255,255,255,.23)}.tcn-footer-logo img,.tcn-footer-about>img{display:block;width:285px;max-height:86px;object-fit:contain;object-position:left center}.tcn-footer-hero-brand p{margin:18px 0 0;color:rgba(255,255,255,.88);font-size:17px;line-height:1.6}
.tcn-footer-hero-support>span{font-size:17px;font-weight:900}.tcn-footer-hero-support h2{margin:5px 0 20px;font-size:31px;line-height:1.15;color:#fff}.tcn-footer-hotlines{display:flex;gap:32px}.tcn-footer-hotlines a{display:flex;align-items:center;gap:13px;color:#fff}.tcn-footer-hotlines i{display:grid;place-items:center;width:58px;height:58px;border:2px solid #3478d0;border-radius:50%;background:#0b4da5;font-style:normal;font-size:25px}.tcn-footer-hotlines i.is-zalo{background:#1489f3;font-size:13px;font-weight:900}.tcn-footer-hotlines b{display:grid;font-weight:400}.tcn-footer-hotlines small{font-size:13px}.tcn-footer-hotlines strong{margin-top:2px;color:#ffbe39;font-size:21px}
.tcn-footer-hero-action{text-align:center}.tcn-footer-cta-btn{display:block;padding:18px 20px;border-radius:14px;background:linear-gradient(135deg,#ffc85b,#f6a817);box-shadow:0 11px 24px rgba(245,158,11,.22);color:#07366f;font-size:17px;font-weight:900;transition:.3s}.tcn-footer-cta-btn:hover{transform:translateY(-4px);color:#07366f;box-shadow:0 16px 30px rgba(245,158,11,.3)}.tcn-footer-hero-action p{margin:12px 0 0;color:rgba(255,255,255,.8);font-size:14px}
.tcn-footer-trust{display:grid;grid-template-columns:repeat(4,1fr);margin:23px 0 0;padding:22px 0 30px;border-bottom:1px solid rgba(255,255,255,.2)}.tcn-footer-trust-item{display:flex;align-items:center;gap:17px;padding:0 30px;border-right:1px solid rgba(255,255,255,.22)}.tcn-footer-trust-item:last-child{border-right:0}.tcn-footer-trust-item i{flex:0 0 66px;display:grid;place-items:center;width:66px;height:66px;border:2px solid #3179d7;border-radius:50%;background:linear-gradient(145deg,#145ec1,#083b87);box-shadow:0 9px 20px rgba(0,0,0,.15);font-size:29px;font-weight:900;font-style:normal;transition:.3s}.tcn-footer-trust-item:hover i{transform:translateY(-5px) scale(1.05);border-color:#ffbd3d}.tcn-footer-trust-item span{display:grid}.tcn-footer-trust-item strong{font-size:17px}.tcn-footer-trust-item small{margin-top:6px;color:rgba(255,255,255,.77);font-size:14px;line-height:1.45}
.tcn-footer-links{display:grid;grid-template-columns:1.18fr 1fr .85fr 1.05fr .78fr;gap:40px;padding:34px 0 38px}.tcn-footer-about{padding-right:30px;border-right:1px solid rgba(255,255,255,.17)}.tcn-footer-about p{margin:18px 0;color:rgba(255,255,255,.82);font-size:16px;line-height:1.65}.tcn-footer-social{display:flex;gap:10px}.tcn-footer-social a{display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#0d57b5;border:1px solid #347edb;color:#fff;font-weight:900}.tcn-footer-social a:nth-child(3){background:#d92525}.tcn-footer-social a:nth-child(4){background:#081a35}
.tcn-footer-col h3,.tcn-footer-qr h3{position:relative;margin:0 0 20px;padding-bottom:12px;color:#fff;font-size:18px;font-weight:900}.tcn-footer-col h3:after,.tcn-footer-qr h3:after{content:"";position:absolute;left:0;bottom:0;width:42px;height:2px;background:#f5a60f}.tcn-footer-col ul{list-style:none;margin:0;padding:0}.tcn-footer-col li{margin-bottom:12px}.tcn-footer-col li a{position:relative;padding-left:17px;color:rgba(255,255,255,.84);font-size:15.5px;transition:.25s}.tcn-footer-col li a:before{content:"›";position:absolute;left:0}.tcn-footer-col li a:hover{padding-left:22px;color:#ffc24e}
.tcn-footer-contact p{display:flex;gap:11px;margin:0 0 16px;color:rgba(255,255,255,.84);font-size:14.5px;line-height:1.55}.tcn-footer-contact i{flex:0 0 36px;display:grid;place-items:center;width:36px;height:36px;border:1px solid rgba(255,255,255,.34);border-radius:50%;font-style:normal}
.tcn-footer-qr{padding:20px;border:1px solid rgba(255,255,255,.25);border-radius:15px;align-self:start;background:rgba(255,255,255,.025)}.tcn-footer-qr-placeholder{display:grid;place-items:center;width:130px;height:130px;margin:0 auto 13px;border:8px solid #fff;border-radius:10px;background:repeating-conic-gradient(#08162a 0 8%,#fff 0 16%);color:#fff;box-shadow:0 7px 16px rgba(0,0,0,.15)}.tcn-footer-qr-placeholder strong{display:grid;place-items:center;width:55px;height:55px;border-radius:50%;background:#07172d;font-size:13px}.tcn-footer-qr-placeholder span{display:none}.tcn-footer-qr p{margin:0;text-align:center;color:rgba(255,255,255,.82);font-size:14px;line-height:1.5}
.tcn-footer-bottom{position:relative;z-index:2;border-top:1px solid rgba(255,255,255,.16);background:rgba(1,24,53,.4)}.tcn-footer-bottom .container{display:grid;grid-template-columns:1fr 1.2fr .8fr;align-items:center;gap:25px;min-height:78px}.tcn-footer-bottom p{margin:0;color:rgba(255,255,255,.73);font-size:14px}.tcn-footer-bottom nav{display:flex;justify-content:center;gap:14px}.tcn-footer-bottom a{color:rgba(255,255,255,.76);font-size:14px}.tcn-footer-bottom a:hover{color:#ffc24e}.tcn-footer-bottom strong{justify-self:end;color:#ffb82e;font-size:17px}.tcn-footer-bottom strong small{display:block;color:rgba(255,255,255,.72);font-size:11px;font-weight:400}
@keyframes tcnFooterReveal{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}.tcn-footer-hero,.tcn-footer-trust,.tcn-footer-links{animation:tcnFooterReveal .8s cubic-bezier(.2,.75,.3,1) both}.tcn-footer-trust{animation-delay:.12s}.tcn-footer-links{animation-delay:.22s}
@media(max-width:1200px){.tcn-footer-hero{grid-template-columns:1fr 1.45fr}.tcn-footer-hero-action{grid-column:1/-1}.tcn-footer-links{grid-template-columns:repeat(2,1fr)}.tcn-footer-qr{max-width:280px}.tcn-footer-trust{grid-template-columns:repeat(2,1fr);row-gap:25px}.tcn-footer-trust-item:nth-child(2){border-right:0}}
@media(max-width:700px){.tcn-footer{padding-top:25px}.tcn-footer-hero{grid-template-columns:1fr;padding:27px 21px;gap:26px}.tcn-footer-hero-brand{padding:0 0 24px;border-right:0;border-bottom:1px solid rgba(255,255,255,.2)}.tcn-footer-hotlines{flex-direction:column;gap:14px}.tcn-footer-hero-support h2{font-size:26px}.tcn-footer-trust{grid-template-columns:1fr}.tcn-footer-trust-item{padding:17px 4px;border-right:0;border-bottom:1px solid rgba(255,255,255,.12)}.tcn-footer-links{grid-template-columns:1fr;gap:31px}.tcn-footer-about{padding-right:0;border-right:0}.tcn-footer-bottom .container{display:flex;flex-direction:column;padding:21px 18px;text-align:center}.tcn-footer-bottom nav{flex-wrap:wrap}.tcn-footer-bottom strong{justify-self:auto}}
@media(prefers-reduced-motion:reduce){.tcn-footer *{animation:none!important;transition:none!important}}
/* Nút quay lên đầu trang */
.tcn-back-to-top{
  position:fixed;
  right:24px;
  bottom:24px;
  z-index:999;
  display:grid;
  place-items:center;
  width:52px;
  height:52px;
  padding:0;
  border:1px solid rgba(255,255,255,.45);
  border-radius:50%;
  background:linear-gradient(135deg,#0b5bb5,#073f80);
  box-shadow:0 10px 28px rgba(3,35,78,.28);
  color:#fff;
  cursor:pointer;
  opacity:0;
  visibility:hidden;
  transform:translateY(12px);
  transition:opacity .25s ease,visibility .25s ease,transform .25s ease,box-shadow .25s ease;
}
.tcn-back-to-top.is-visible{
  opacity:1;
  visibility:visible;
  transform:translateY(0);
}
.tcn-back-to-top:hover{
  transform:translateY(-3px);
  box-shadow:0 14px 32px rgba(3,35,78,.36);
}
.tcn-back-to-top:focus-visible{
  outline:3px solid #f59e0b;
  outline-offset:3px;
}
.tcn-back-to-top svg{
  width:25px;
  height:25px;
  fill:currentColor;
}
@media (max-width:767px){
  .tcn-back-to-top{
    right:16px;
    bottom:16px;
    width:46px;
    height:46px;
  }
}
/* ========================================
   FRONT PAGE - HERO
   Bố cục bám theo mẫu desktop
======================================== */
.hero{
  position:relative;
  overflow:hidden;
  width:100%;
  min-height:690px;
  background:#063b7d;
  color:#fff;
}
/* ========================================
   BACKGROUND IMAGE
======================================== */
.hero-bg{
  position:absolute;
  inset:0;
  z-index:0;
  width:100%;
  height:100%;
  object-fit:cover;
  object-position:center center;
  pointer-events:none;
  user-select:none;
}
/* ========================================
   OVERLAY
======================================== */
.hero-overlay{
  position:absolute;
  inset:0;
  z-index:1;
  background:linear-gradient(
    90deg,
    rgba(3,38,82,.82) 0%,
    rgba(4,54,111,.62) 30%,
    rgba(8,88,180,.20) 53%,
    rgba(8,88,180,0) 72%
  );
  pointer-events:none;
}
/* ========================================
   GRID
======================================== */
.hero-grid{
  position:relative;
  z-index:2;
  width:min(1440px,calc(100% - 56px));
  min-height:690px;
  margin:0 auto;
  display:grid;
  grid-template-columns:
    minmax(500px,560px)
    410px
    1fr;
  align-items:center;
  column-gap:44px;
  padding:64px 0 72px;
}
/* ========================================
   HERO COPY
======================================== */
.hero-copy{
  grid-column:1;
  width:100%;
  max-width:560px;
}
.hero .eyebrow{
  display:inline-block;
  margin:0 0 16px;
  color:#f7a400;
  font-size:16px;
  line-height:1.2;
  font-weight:800;
  letter-spacing:1.4px;
}
/* TITLE */
.hero h1{
  margin:0 0 22px;
  color:#fff;
  font-size:60px;
  line-height:1.06;
  font-weight:800;
  letter-spacing:-1.5px;
}
/* DESCRIPTION */
.hero-lead{
  max-width:535px;
  margin:0;
  color:rgba(255,255,255,.96);
  font-size:20px;
  line-height:1.7;
  font-weight:400;
}
/* ========================================
   ACTIONS
======================================== */
.hero-actions{
  display:flex;
  align-items:center;
  flex-wrap:wrap;
  gap:18px;
  margin:30px 0 24px;
}
.hero-actions .btn{
  min-height:58px;
  padding:0 30px;
  border-radius:9px;
  font-size:15px;
  font-weight:800;
}
.hero .btn-primary{
  min-width:255px;
  background:#f59e0b;
  color:#172033;
}
.hero .btn-light{
  min-width:265px;
  background:#fff;
  color:#0b4da2;
}
/* ========================================
   POINTS
======================================== */
.hero-points{
  display:flex;
  align-items:center;
  flex-wrap:wrap;
  gap:30px;
  color:#fff;
  font-size:15px;
  font-weight:600;
}
/* ========================================
   HERO CARD
======================================== */
.hero-card{
  grid-column:2;
  position:relative;
  z-index:3;
  width:410px;
  margin:0;
  padding:42px 36px 34px;
  background:rgba(255,255,255,.98);
  color:var(--tcn-text);
  border-radius:24px;
  box-shadow:0 20px 55px rgba(0,31,77,.25);
}
/* BADGE */
.hero-card-badge{
  display:inline-block;
  padding:8px 13px;
  background:#fff2d1;
  color:#ad6800;
  border-radius:999px;
  font-size:13px;
  font-weight:800;
  line-height:1.2;
}
/* CARD TITLE */
.hero-card h3{
  margin:20px 0 14px;
  color:#172033;
  font-size:33px;
  line-height:1.18;
  font-weight:800;
}
/* CARD DESCRIPTION */
.hero-card p{
  margin:0 0 24px;
  color:#667085;
  font-size:16px;
  line-height:1.65;
}
/* CARD BUTTON */
.hero-card .btn-block{
  display:flex;
  align-items:center;
  justify-content:center;
  width:100%;
  min-height:56px;
  padding:0 20px;
  border-radius:8px;
  background:#f59e0b;
  color:#172033;
  font-size:16px;
  font-weight:800;
  text-align:center;
}
/* CARD SMALL TEXT */
.hero-card small{
  display:block;
  margin-top:15px;
  color:#8a94a6;
  font-size:12px;
  line-height:1.5;
  text-align:center;
}
/* ========================================
   LAPTOP
======================================== */
@media(max-width:1450px){
  .hero-grid{
    width:min(1280px,calc(100% - 48px));
    grid-template-columns:
      minmax(440px,520px)
      380px
      1fr;
    column-gap:34px;
  }
  .hero h1{
    font-size:54px;
  }
  .hero-lead{
    font-size:18px;
  }
  .hero-card{
    width:380px;
    padding:36px 32px 32px;
  }
  .hero-card h3{
    font-size:30px;
  }
  .hero-card p{
    font-size:15px;
  }
  .hero-actions .btn{
    min-width:0;
  }
}
/* ========================================
   TABLET
======================================== */
@media(max-width:1100px){
  .hero{
    min-height:auto;
  }
  .hero-bg{
    object-position:68% center;
  }
  .hero-overlay{
    background:rgba(4,54,111,.78);
  }
  .hero-grid{
    min-height:auto;
    grid-template-columns:
      minmax(0,1fr)
      370px;
    gap:32px;
    padding:56px 0;
  }
  .hero-copy{
    grid-column:1;
  }
  .hero-card{
    grid-column:2;
    width:100%;
  }
  .hero h1{
    font-size:46px;
  }
  .hero-lead{
    font-size:17px;
  }
  .hero-card h3{
    font-size:29px;
  }
}
/* ========================================
   MOBILE / SMALL TABLET
======================================== */
@media(max-width:820px){
  .hero-bg{
    object-position:70% center;
  }
  .hero-overlay{
    background:rgba(4,54,111,.88);
  }
  .hero-grid{
    width:min(100% - 32px,680px);
    grid-template-columns:1fr;
    gap:34px;
    padding:46px 0;
  }
  .hero-copy,
  .hero-card{
    grid-column:1;
  }
  .hero-card{
    width:100%;
    max-width:520px;
  }
  .hero h1{
    font-size:42px;
  }
  .hero-lead{
    font-size:17px;
  }
}
/* ========================================
   MOBILE
======================================== */
@media(max-width:560px){
  .hero-grid{
    width:calc(100% - 28px);
  }
  .hero h1{
    font-size:36px;
  }
  .hero .eyebrow{
    font-size:13px;
  }
  .hero-lead{
    font-size:16px;
  }
  .hero-actions{
    flex-direction:column;
    align-items:stretch;
    gap:12px;
  }
  .hero-actions .btn{
    width:100%;
    min-width:0;
  }
  .hero-points{
    flex-direction:column;
    align-items:flex-start;
    gap:8px;
  }
  .hero-card{
    padding:28px 22px;
  }
  .hero-card-badge{
    font-size:12px;
  }
  .hero-card h3{
    font-size:28px;
  }
  .hero-card p{
    font-size:15px;
  }
  .hero-card .btn-block{
    font-size:15px;
  }
  .hero-card small{
    font-size:11px;
  }
}
/* ========================================
   LOAN SOLUTIONS
======================================== */
.tcn-loan-solutions{
  position:relative;
  padding:80px 0 70px;
  background:
    linear-gradient(
      180deg,
      #f9fbff 0%,
      #ffffff 45%,
      #f7faff 100%
    );
}
/* ========================================
   HEADING
======================================== */
.tcn-loan-heading{
  max-width:1100px;
  margin:0 auto 50px;
  text-align:center;
}
.tcn-loan-eyebrow{
  display:block;
  margin-bottom:12px;
  color:#f59e0b;
  font-size:20px;
  font-weight:800;
  letter-spacing:.6px;
  text-transform:uppercase;
}
.tcn-loan-title-wrap{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:32px;
}
.tcn-title-line{
  width:110px;
  height:2px;
  background:#174da8;
}
.tcn-loan-heading h2{
  margin:0;
  color:#123a8f;
  font-size:52px;
  line-height:1.12;
  font-weight:800;
  letter-spacing:-1.2px;
}
.tcn-title-accent{
  display:block;
  width:76px;
  height:4px;
  margin:16px auto 20px;
  background:#f59e0b;
  border-radius:999px;
}
.tcn-loan-heading p{
  margin:0;
  color:#667085;
  font-size:20px;
  line-height:1.7;
}
/* ========================================
   GRID
======================================== */
.tcn-loan-grid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:28px;
}
/* ========================================
   CARD
======================================== */
.tcn-loan-card{
  position:relative;
  display:flex;
  flex-direction:column;
  min-width:0;
  overflow:hidden;
  background:#fff;
  border:1px solid #e5eaf1;
  border-radius:18px;
  box-shadow:
    0 12px 35px rgba(11,91,181,.10);
  transition:
    transform .25s ease,
    box-shadow .25s ease,
    border-color .25s ease;
}
.tcn-loan-card:hover{
  transform:translateY(-6px);
  border-color:#c9daf3;
  box-shadow:
    0 20px 45px rgba(11,91,181,.16);
}
/* ========================================
   CARD IMAGE
======================================== */
.tcn-loan-image{
  position:relative;
  width:100%;
  height:225px;
  overflow:hidden;
  background:#eef5ff;
}
.tcn-loan-image img{
  display:block;
  width:100%;
  height:100%;
  object-fit:cover;
  transition:transform .4s ease;
}
.tcn-loan-card:hover .tcn-loan-image img{
  transform:scale(1.04);
}
/* ========================================
   CONTENT
======================================== */
.tcn-loan-content{
  display:flex;
  flex-direction:column;
  flex:1;
  padding:28px 26px 26px;
}
.tcn-loan-content h3{
  min-height:68px;
  margin:0 0 14px;
  color:#123a8f;
  font-size:26px;
  line-height:1.3;
  font-weight:800;
  text-align:center;
}
.tcn-loan-desc{
  min-height:88px;
  margin:0;
  color:#667085;
  font-size:17px;
  line-height:1.7;
  text-align:center;
}
.tcn-loan-divider{
  width:100%;
  height:1px;
  margin:22px 0;
  background:#e5eaf1;
}
/* ========================================
   FEATURES
======================================== */
.tcn-loan-features{
  list-style:none;
  margin:0 0 26px;
  padding:0;
  display:flex;
  flex-direction:column;
  gap:12px;
}
.tcn-loan-features li{
  position:relative;
  padding-left:28px;
  color:#344054;
  font-size:17px;
  line-height:1.55;
}
.tcn-loan-features li:before{
  content:"✓";
  position:absolute;
  left:0;
  top:2px;
  display:flex;
  align-items:center;
  justify-content:center;
  width:18px;
  height:18px;
  background:#0b5bb5;
  color:#fff;
  border-radius:50%;
  font-size:11px;
  font-weight:800;
}
/* ========================================
   BUTTON
======================================== */
.tcn-loan-btn{
  margin-top:auto;
  min-height:56px;
  padding:0 22px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:12px;
  background:
    linear-gradient(
      135deg,
      #073f80 0%,
      #0b5bb5 100%
    );
  color:#fff;
  border-radius:9px;
  font-size:17px;
  font-weight:800;
  text-decoration:none;
  transition:
    transform .2s ease,
    box-shadow .2s ease;
}
.tcn-loan-btn:hover{
  color:#fff;
  transform:translateY(-2px);
  box-shadow:
    0 10px 22px rgba(11,91,181,.24);
}
.tcn-loan-btn-arrow{
  font-size:22px;
  line-height:1;
}
/* ========================================
   BENEFITS
======================================== */
.tcn-loan-benefits{
  margin-top:38px;
  padding:30px 32px;
  display:grid;
  grid-template-columns:repeat(4,1fr);
  background:#fff;
  border:1px solid #e5eaf1;
  border-radius:18px;
  box-shadow:
    0 12px 30px rgba(11,91,181,.09);
}
.tcn-loan-benefit{
  position:relative;
  padding:6px 28px;
  text-align:center;
}
.tcn-loan-benefit:not(:last-child):after{
  content:"";
  position:absolute;
  right:0;
  top:8px;
  bottom:8px;
  width:1px;
  background:#d9e2ef;
}
.tcn-loan-benefit strong{
  display:block;
  margin-bottom:8px;
  color:#123a8f;
  font-size:19px;
  line-height:1.3;
  font-weight:800;
}
.tcn-loan-benefit span{
  display:block;
  color:#667085;
  font-size:16px;
  line-height:1.5;
}
/* ========================================
   LAPTOP
======================================== */
@media(max-width:1200px){
  .tcn-loan-heading h2{
    font-size:46px;
  }
  .tcn-loan-heading p{
    font-size:18px;
  }
  .tcn-title-line{
    width:80px;
  }
  .tcn-loan-grid{
    gap:20px;
  }
  .tcn-loan-content{
    padding:24px 22px;
  }
  .tcn-loan-content h3{
    font-size:24px;
  }
  .tcn-loan-desc{
    font-size:16px;
  }
  .tcn-loan-features li{
    font-size:16px;
  }
  .tcn-loan-btn{
    font-size:16px;
  }
}
/* ========================================
   TABLET
======================================== */
@media(max-width:991px){
  .tcn-loan-solutions{
    padding:65px 0 60px;
  }
  .tcn-loan-grid{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
  .tcn-loan-heading h2{
    font-size:40px;
  }
  .tcn-loan-heading p{
    font-size:18px;
  }
  .tcn-title-line{
    width:60px;
  }
  .tcn-loan-benefits{
    grid-template-columns:repeat(2,1fr);
    row-gap:25px;
  }
  .tcn-loan-benefit:nth-child(2):after{
    display:none;
  }
}
/* ========================================
   MOBILE
======================================== */
@media(max-width:600px){
  .tcn-loan-solutions{
    padding:52px 0;
  }
  .tcn-loan-heading{
    margin-bottom:32px;
  }
  .tcn-loan-eyebrow{
    font-size:16px;
  }
  .tcn-loan-title-wrap{
    gap:14px;
  }
  .tcn-title-line{
    width:30px;
  }
  .tcn-loan-heading h2{
    font-size:34px;
  }
  .tcn-loan-heading p{
    font-size:17px;
  }
  .tcn-loan-grid{
    grid-template-columns:1fr;
    gap:22px;
  }
  .tcn-loan-image{
    height:230px;
  }
  .tcn-loan-content{
    padding:24px 20px;
  }
  .tcn-loan-content h3{
    min-height:auto;
    font-size:25px;
  }
  .tcn-loan-desc{
    min-height:auto;
    font-size:16px;
  }
  .tcn-loan-features li{
    font-size:16px;
  }
  .tcn-loan-btn{
    min-height:54px;
    font-size:16px;
  }
  .tcn-loan-benefits{
    grid-template-columns:1fr;
    padding:22px;
  }
  .tcn-loan-benefit{
    padding:16px 10px;
  }
  .tcn-loan-benefit:not(:last-child):after{
    top:auto;
    left:10%;
    right:10%;
    bottom:0;
    width:auto;
    height:1px;
  }
  .tcn-loan-benefit strong{
    font-size:18px;
  }
  .tcn-loan-benefit span{
    font-size:15px;
  }
}
/* FRONT PAGE: BENEFITS */
.benefit-cards article{background:#fff;border:1px solid var(--tcn-border);border-radius:16px;padding:30px;box-shadow:0 8px 24px rgba(8,44,87,.05)}
.benefit-icon{width:58px;height:58px;border-radius:14px;display:grid;place-items:center;background:#eaf3ff;color:var(--tcn-primary);font-size:28px;font-weight:800}
.benefit-cards h3{font-size:22px;margin:18px 0 7px}
.benefit-cards p{color:var(--tcn-muted)}
.quick-cta{margin-top:30px;background:var(--tcn-primary);border-radius:16px;padding:24px 28px;color:#fff;display:flex;align-items:center;justify-content:center;gap:30px}
.quick-cta strong{font-size:22px}
@media(max-width:680px){.quick-cta{flex-direction:column;text-align:center}}
/* ========================================
   SECTION 3 - HỆ SINH THÁI ĐỐI TÁC
======================================== */
.tcn-partners{position:relative;overflow:hidden;padding:78px 0 86px;background:#eef7ff none center/cover no-repeat;color:#0b2f70}
.tcn-partners:before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(255,255,255,.18),rgba(238,247,255,.05));pointer-events:none}
.tcn-partners-inner{position:relative;z-index:1}
.tcn-partners-heading{max-width:1050px;margin:0 auto 34px;text-align:center}
.tcn-partners-eyebrow{display:block;margin-bottom:8px;color:#f59e0b;font-size:20px;font-weight:800;letter-spacing:.6px}
.tcn-partners-title-wrap{display:flex;align-items:center;justify-content:center;gap:20px}
.tcn-partners-title-wrap h2{margin:0;color:#0a3e91;font-size:clamp(34px,3.5vw,54px);line-height:1.15;font-weight:900;text-transform:uppercase}
.tcn-partners-line{width:95px;height:2px;background:#1765cf;position:relative;flex:0 0 auto}
.tcn-partners-line:before{content:"";position:absolute;width:8px;height:8px;border-radius:50%;background:#1765cf;top:50%;transform:translateY(-50%)}
.tcn-partners-line:first-child:before{left:0}.tcn-partners-line:last-child:before{right:0}
.tcn-partners-accent{display:block;width:80px;height:5px;margin:13px auto 14px;border-radius:99px;background:#1765cf}
.tcn-partners-heading p{margin:0;color:#284c7e;font-size:20px;line-height:1.65}
.tcn-partners-banner{width:min(850px,76%);min-height:68px;margin:0 0 30px;padding:13px 30px;display:flex;align-items:center;gap:18px;color:#fff;background:linear-gradient(135deg,#063b9b,#0877dc);border-radius:10px 10px 10px 4px;box-shadow:0 12px 25px rgba(6,73,160,.2);font-size:clamp(24px,2.3vw,36px)}
.tcn-partners-bank-icon{font-size:38px;line-height:1;color:#fff}
.tcn-partners-network{display:grid;grid-template-columns:minmax(0,1fr) 330px minmax(0,1fr);gap:34px;align-items:center}
.tcn-partners-column{display:grid;gap:18px}
.tcn-partner-card{min-height:122px;display:grid;grid-template-columns:46% 54%;align-items:center;background:rgba(255,255,255,.94);border:1px solid rgba(14,91,181,.13);border-left:4px solid #1265ca;border-radius:18px;padding:18px 20px;box-shadow:0 12px 30px rgba(15,74,135,.12)}
.tcn-partner-logo{height:70px;padding-right:18px;border-right:1px solid #bad1ef;display:flex;align-items:center;justify-content:center}
.tcn-partner-logo img{display:block;max-width:100%;max-height:62px;width:auto;height:auto;object-fit:contain}
.tcn-partner-card ul{margin:0;padding:0 0 0 28px;color:#123d78;font-size:18px;line-height:1.75}
.tcn-partners-center{position:relative;width:300px;height:300px;margin:auto;display:grid;place-items:center}
.tcn-orbit{position:absolute;border-radius:50%;border:1px solid rgba(26,112,221,.55)}
.tcn-orbit-1{inset:0}.tcn-orbit-2{inset:20px;border-width:2px;border-color:rgba(67,156,255,.35)}
.tcn-partners-core{position:relative;width:218px;height:218px;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;text-align:center;background:radial-gradient(circle at 40% 30%,#1678df,#063c99 68%);border:10px solid #cbe7ff;box-shadow:0 0 0 8px rgba(35,130,230,.2),0 15px 30px rgba(5,61,145,.24)}
.tcn-handshake{font-size:58px;line-height:1;margin-bottom:10px;filter:grayscale(1) brightness(0) invert(1)}
.tcn-partners-core strong{font-size:20px}.tcn-partners-core small{font-size:16px;font-weight:800;margin-top:2px}
.tcn-partners-benefits{margin-top:34px;display:grid;grid-template-columns:repeat(4,1fr);background:rgba(255,255,255,.95);border:1px solid rgba(20,88,165,.12);border-radius:18px;box-shadow:0 12px 30px rgba(15,74,135,.12);padding:25px 22px}
.tcn-partners-benefit{display:grid;grid-template-columns:62px 1fr;gap:14px;align-items:center;padding:0 22px;border-right:1px solid #c9d9ed}
.tcn-partners-benefit:last-child{border-right:0}
.tcn-partners-benefit>span{width:58px;height:58px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(145deg,#0b64cc,#073e96);color:#fff;font-size:27px;font-weight:900;box-shadow:0 7px 15px rgba(11,91,181,.2)}
.tcn-partners-benefit strong{display:block;margin-bottom:4px;color:#0a3d88;font-size:18px}.tcn-partners-benefit small{display:block;color:#38567d;font-size:15px;line-height:1.5}
@media(max-width:1100px){.tcn-partners-network{grid-template-columns:1fr 250px 1fr;gap:18px}.tcn-partners-center{width:240px;height:240px}.tcn-partners-core{width:178px;height:178px}.tcn-partner-card{grid-template-columns:1fr;padding:16px}.tcn-partner-logo{border-right:0;border-bottom:1px solid #d7e3f2;padding:0 0 10px;margin-bottom:8px}.tcn-partner-card ul{padding-left:22px}.tcn-partners-benefits{grid-template-columns:1fr 1fr;gap:24px}.tcn-partners-benefit:nth-child(2){border-right:0}}
@media(max-width:780px){.tcn-partners{padding:58px 0;background-position:65% center}.tcn-partners-title-wrap{gap:10px}.tcn-partners-line{width:32px}.tcn-partners-heading p br{display:none}.tcn-partners-banner{width:100%;font-size:22px;padding:14px 18px}.tcn-partners-network{grid-template-columns:1fr}.tcn-partners-center{order:-1;width:220px;height:220px}.tcn-partners-core{width:164px;height:164px}.tcn-handshake{font-size:44px}.tcn-partner-card{grid-template-columns:40% 60%}.tcn-partner-logo{border-bottom:0;border-right:1px solid #d7e3f2;padding:0 14px 0 0;margin:0}.tcn-partners-benefits{grid-template-columns:1fr}.tcn-partners-benefit,.tcn-partners-benefit:nth-child(2){border-right:0;border-bottom:1px solid #d5e2f1;padding:0 0 20px}.tcn-partners-benefit:last-child{border-bottom:0;padding-bottom:0}}
@media(max-width:480px){.tcn-partners-title-wrap h2{font-size:31px}.tcn-partners-line{display:none}.tcn-partners-eyebrow{font-size:16px}.tcn-partner-card{grid-template-columns:1fr}.tcn-partner-logo{border-right:0;border-bottom:1px solid #d7e3f2;padding:0 0 10px;margin-bottom:8px}.tcn-partners-banner{font-size:20px}.tcn-partners-bank-icon{font-size:30px}}
/* ========================================
   ANIMATION - SECTION 3
======================================== */
/* Hiệu ứng xuất hiện */
@keyframes tcnFadeUp{
  0%{opacity:0;transform:translateY(28px)}
  100%{opacity:1;transform:translateY(0)}
}
@keyframes tcnSlideLeft{
  0%{opacity:0;transform:translateX(-42px)}
  100%{opacity:1;transform:translateX(0)}
}
@keyframes tcnSlideRight{
  0%{opacity:0;transform:translateX(42px)}
  100%{opacity:1;transform:translateX(0)}
}
/* Chuyển động vòng tròn trung tâm */
@keyframes tcnOrbitSpin{
  from{transform:rotate(0deg)}
  to{transform:rotate(360deg)}
}
@keyframes tcnOrbitSpinReverse{
  from{transform:rotate(360deg)}
  to{transform:rotate(0deg)}
}
@keyframes tcnCoreFloat{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(-9px)}
}
@keyframes tcnCoreGlow{
  0%,100%{
    box-shadow:
      0 0 0 8px rgba(35,130,230,.18),
      0 15px 30px rgba(5,61,145,.24)
  }
  50%{
    box-shadow:
      0 0 0 14px rgba(35,130,230,.08),
      0 18px 38px rgba(5,61,145,.32)
  }
}
@keyframes tcnIconPulse{
  0%,100%{transform:scale(1)}
  50%{transform:scale(1.08)}
}
/* Heading */
.tcn-partners-heading{
  animation:tcnFadeUp .75s cubic-bezier(.2,.75,.3,1) both;
}
.tcn-partners-banner{
  animation:tcnFadeUp .75s .12s cubic-bezier(.2,.75,.3,1) both;
  transition:transform .3s ease,box-shadow .3s ease;
}
.tcn-partners-banner:hover{
  transform:translateY(-4px);
  box-shadow:0 18px 36px rgba(6,73,160,.27);
}
/* Card ngân hàng */
.tcn-partners-column:first-child .tcn-partner-card{
  animation:tcnSlideLeft .72s cubic-bezier(.2,.75,.3,1) both;
}
.tcn-partners-column:last-child .tcn-partner-card{
  animation:tcnSlideRight .72s cubic-bezier(.2,.75,.3,1) both;
}
.tcn-partners-column .tcn-partner-card:nth-child(1){animation-delay:.12s}
.tcn-partners-column .tcn-partner-card:nth-child(2){animation-delay:.24s}
.tcn-partners-column .tcn-partner-card:nth-child(3){animation-delay:.36s}
.tcn-partner-card{
  position:relative;
  overflow:hidden;
  transition:
    transform .32s cubic-bezier(.2,.75,.3,1),
    box-shadow .32s ease,
    border-color .32s ease;
  will-change:transform;
}
.tcn-partner-card:before{
  content:"";
  position:absolute;
  top:0;
  left:-120%;
  width:55%;
  height:100%;
  background:linear-gradient(
    110deg,
    transparent 0%,
    rgba(255,255,255,.15) 25%,
    rgba(255,255,255,.7) 50%,
    rgba(255,255,255,.15) 75%,
    transparent 100%
  );
  transform:skewX(-18deg);
  transition:left .7s ease;
  pointer-events:none;
}
.tcn-partner-card:hover{
  transform:translateY(-7px) scale(1.012);
  border-color:rgba(14,91,181,.28);
  box-shadow:0 20px 42px rgba(15,74,135,.18);
}
.tcn-partner-card:hover:before{
  left:145%;
}
.tcn-partner-logo img{
  transition:transform .32s ease,filter .32s ease;
}
.tcn-partner-card:hover .tcn-partner-logo img{
  transform:scale(1.07);
  filter:drop-shadow(0 7px 10px rgba(8,65,135,.14));
}
/* Khối trung tâm */
.tcn-partners-center{
  animation:tcnFadeUp .75s .2s cubic-bezier(.2,.75,.3,1) both;
}
.tcn-orbit{
  will-change:transform;
}
.tcn-orbit-1{
  animation:tcnOrbitSpin 18s linear infinite;
}
.tcn-orbit-2{
  animation:tcnOrbitSpinReverse 13s linear infinite;
}
.tcn-orbit-1:before,
.tcn-orbit-2:before{
  content:"";
  position:absolute;
  width:10px;
  height:10px;
  border-radius:50%;
  background:#1d7ee4;
  box-shadow:0 0 0 5px rgba(29,126,228,.12);
}
.tcn-orbit-1:before{
  top:17px;
  left:52px;
}
.tcn-orbit-2:before{
  right:20px;
  bottom:37px;
  width:8px;
  height:8px;
}
.tcn-partners-core{
  animation:
    tcnCoreFloat 4s ease-in-out infinite,
    tcnCoreGlow 3s ease-in-out infinite;
}
.tcn-handshake{
  animation:tcnIconPulse 2.4s ease-in-out infinite;
}
/* 4 lợi ích phía dưới */
.tcn-partners-benefits{
  animation:tcnFadeUp .8s .35s cubic-bezier(.2,.75,.3,1) both;
}
.tcn-partners-benefit{
  transition:transform .3s ease;
}
.tcn-partners-benefit:hover{
  transform:translateY(-4px);
}
.tcn-partners-benefit>span{
  transition:transform .32s ease,box-shadow .32s ease;
}
.tcn-partners-benefit:hover>span{
  transform:translateY(-3px) scale(1.08);
  box-shadow:0 12px 24px rgba(11,91,181,.27);
}
/* Mobile: giảm độ mạnh animation để mượt hơn */
@media(max-width:780px){
  .tcn-partners-column:first-child .tcn-partner-card,
  .tcn-partners-column:last-child .tcn-partner-card{
    animation-name:tcnFadeUp;
  }
  .tcn-partner-card:hover{
    transform:translateY(-4px);
  }
  .tcn-orbit-1{animation-duration:22s}
  .tcn-orbit-2{animation-duration:17s}
}
/* Tôn trọng cài đặt giảm chuyển động của người dùng */
@media(prefers-reduced-motion:reduce){
  .tcn-partners *,
  .tcn-partners *:before,
  .tcn-partners *:after{
    animation:none!important;
    transition:none!important;
    scroll-behavior:auto!important;
  }
}
/* =========================================================
   SECTION 4 - CHÍNH SÁCH KHOẢN VAY
   ========================================================= */
.tcn-policy{
  position:relative;
  overflow:hidden;
  padding:82px 0 72px;
  background:
    linear-gradient(rgba(244,250,255,.76),rgba(240,248,255,.84)),
    none center/cover no-repeat;
  color:var(--tcn-text);
}
.tcn-policy:before{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  background:radial-gradient(circle at 50% 22%,rgba(255,255,255,.9),transparent 44%);
}
.tcn-policy .container{position:relative;z-index:1}
.tcn-policy-heading{text-align:center;max-width:1080px;margin:0 auto 38px}
.tcn-policy-eyebrow{
  display:inline-flex;
  align-items:center;
  gap:12px;
  padding:10px 24px;
  border:1px solid rgba(22,112,226,.38);
  border-radius:999px;
  background:rgba(255,255,255,.92);
  color:#0b56b6;
  box-shadow:0 8px 24px rgba(9,69,145,.10);
  font-size:22px;
  line-height:1;
  font-weight:800;
  letter-spacing:.2px;
}
.tcn-policy-eyebrow img{width:42px;height:36px;object-fit:contain}
.tcn-policy-heading h2{
  margin:22px 0 12px;
  color:#082d7d;
  font-size:clamp(42px,4.2vw,64px);
  line-height:1.02;
  font-weight:900;
  letter-spacing:-1.4px;
}
.tcn-policy-heading p{
  margin:0;
  color:#173971;
  font-size:clamp(19px,1.6vw,25px);
  line-height:1.55;
  font-weight:500;
}
.tcn-policy-title-line{
  display:block;
  width:280px;
  height:4px;
  margin:22px auto 0;
  border-radius:10px;
  background:linear-gradient(90deg,transparent,#0b5bb5 24%,#1f82e7 50%,#0b5bb5 76%,transparent);
}
.tcn-policy-grid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:22px;
}
.tcn-policy-card{
  min-height:238px;
  display:grid;
  grid-template-columns:142px minmax(0,1fr);
  align-items:center;
  gap:18px;
  padding:26px 28px;
  border:1px solid rgba(38,132,229,.30);
  border-radius:24px;
  background:rgba(255,255,255,.94);
  box-shadow:0 12px 30px rgba(21,77,139,.10);
  transition:transform .32s ease,box-shadow .32s ease,border-color .32s ease;
  overflow:hidden;
}
.tcn-policy-card:hover{
  transform:translateY(-7px);
  border-color:rgba(25,113,216,.52);
  box-shadow:0 20px 42px rgba(21,77,139,.17);
}
.tcn-policy-icon{
  display:flex;
  align-items:center;
  justify-content:center;
}
.tcn-policy-icon img{
  width:122px;
  height:122px;
  object-fit:contain;
  filter:drop-shadow(0 9px 12px rgba(9,65,140,.15));
  transition:transform .35s ease,filter .35s ease;
}
.tcn-policy-card:hover .tcn-policy-icon img{
  transform:translateY(-4px) scale(1.07) rotate(-1deg);
  filter:drop-shadow(0 13px 16px rgba(9,65,140,.22));
}
.tcn-policy-card-content h3{
  position:relative;
  margin:0 0 16px;
  padding-bottom:12px;
  color:#0751b4;
  font-size:24px;
  line-height:1.2;
  font-weight:900;
}
.tcn-policy-card-content h3:after{
  content:"";
  position:absolute;
  left:0;
  bottom:0;
  width:100%;
  height:2px;
  background:linear-gradient(90deg,#0b5bb5 0 16%,#8bc2ff 16% 100%);
}
.tcn-policy-card-content p{
  margin:0;
  color:#17335f;
  font-size:18px;
  line-height:1.72;
}
.tcn-policy-card-content strong{color:#084ca8;font-weight:900}
.tcn-policy-benefits{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:0;
  margin-top:26px;
  padding:20px 18px;
  border:1px solid rgba(38,132,229,.28);
  border-radius:24px;
  background:rgba(255,255,255,.96);
  box-shadow:0 12px 30px rgba(21,77,139,.10);
}
.tcn-policy-benefit{
  display:grid;
  grid-template-columns:78px 1fr;
  align-items:center;
  gap:14px;
  min-height:92px;
  padding:10px 22px;
  border-right:1px solid rgba(79,142,218,.32);
  transition:transform .28s ease;
}
.tcn-policy-benefit:last-child{border-right:0}
.tcn-policy-benefit:hover{transform:translateY(-4px)}
.tcn-policy-benefit img{
  width:70px;
  height:70px;
  object-fit:contain;
  filter:drop-shadow(0 6px 9px rgba(8,68,145,.14));
  transition:transform .3s ease;
}
.tcn-policy-benefit:hover img{transform:scale(1.08)}
.tcn-policy-benefit strong{
  display:block;
  margin-bottom:6px;
  color:#07459d;
  font-size:19px;
  line-height:1.2;
  font-weight:900;
}
.tcn-policy-benefit small{
  display:block;
  color:#27446f;
  font-size:15.5px;
  line-height:1.5;
}
.tcn-policy-note{
  max-width:980px;
  margin:18px auto 0;
  display:flex;
  align-items:flex-start;
  gap:15px;
  padding:14px 22px;
  border:1px solid rgba(25,102,193,.38);
  border-radius:18px;
  background:rgba(255,255,255,.94);
  box-shadow:0 8px 22px rgba(18,75,139,.08);
}
.tcn-policy-note-icon{
  flex:0 0 38px;
  width:38px;
  height:38px;
  display:grid;
  place-items:center;
  border-radius:50%;
  background:linear-gradient(145deg,#1684ee,#0751b6);
  color:#fff;
  font-size:24px;
  font-weight:900;
  box-shadow:0 6px 14px rgba(11,91,181,.24);
}
.tcn-policy-note p{
  margin:0;
  color:#173a70;
  font-size:16px;
  line-height:1.55;
}
.tcn-policy-note strong{color:#074aa6}
/* Animation */
@keyframes tcnPolicyFadeUp{
  from{opacity:0;transform:translateY(30px)}
  to{opacity:1;transform:translateY(0)}
}
@keyframes tcnPolicyFloat{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(-7px)}
}
@keyframes tcnPolicyShine{
  0%{transform:translateX(-180%) skewX(-18deg)}
  100%{transform:translateX(320%) skewX(-18deg)}
}
.tcn-policy-heading{animation:tcnPolicyFadeUp .75s ease both}
.tcn-policy-card{
  position:relative;
  animation:tcnPolicyFadeUp .72s ease both;
}
.tcn-policy-card:nth-child(1){animation-delay:.08s}
.tcn-policy-card:nth-child(2){animation-delay:.16s}
.tcn-policy-card:nth-child(3){animation-delay:.24s}
.tcn-policy-card:nth-child(4){animation-delay:.32s}
.tcn-policy-card:nth-child(5){animation-delay:.40s}
.tcn-policy-card:nth-child(6){animation-delay:.48s}
.tcn-policy-card:before{
  content:"";
  position:absolute;
  inset:0 auto 0 -40%;
  width:22%;
  pointer-events:none;
  background:linear-gradient(100deg,transparent,rgba(255,255,255,.70),transparent);
  transform:skewX(-18deg);
}
.tcn-policy-card:hover:before{animation:tcnPolicyShine .75s ease}
.tcn-policy-benefits{animation:tcnPolicyFadeUp .8s .48s ease both}
.tcn-policy-note{animation:tcnPolicyFadeUp .8s .58s ease both}
.tcn-policy-eyebrow img,
.tcn-policy-note-icon{animation:tcnPolicyFloat 3.4s ease-in-out infinite}
@media(max-width:1100px){
  .tcn-policy-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .tcn-policy-benefits{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
  .tcn-policy-benefit{border-right:0;border-bottom:1px solid rgba(79,142,218,.24)}
  .tcn-policy-benefit:nth-last-child(-n+2){border-bottom:0}
}
@media(max-width:720px){
  .tcn-policy{padding:58px 0 52px;background-position:center bottom}
  .tcn-policy-eyebrow{font-size:16px;padding:9px 16px;gap:8px}
  .tcn-policy-eyebrow img{width:32px;height:28px}
  .tcn-policy-heading h2{font-size:34px;letter-spacing:-.5px;margin-top:18px}
  .tcn-policy-heading p{font-size:17px}
  .tcn-policy-title-line{width:190px;margin-top:18px}
  .tcn-policy-grid{grid-template-columns:1fr;gap:16px}
  .tcn-policy-card{grid-template-columns:100px 1fr;min-height:auto;padding:21px 18px;border-radius:20px}
  .tcn-policy-icon img{width:90px;height:90px}
  .tcn-policy-card-content h3{font-size:20px;margin-bottom:12px}
  .tcn-policy-card-content p{font-size:16px;line-height:1.62}
  .tcn-policy-benefits{grid-template-columns:1fr;padding:10px 16px}
  .tcn-policy-benefit{grid-template-columns:66px 1fr;padding:14px 6px;border-bottom:1px solid rgba(79,142,218,.24)!important}
  .tcn-policy-benefit:last-child{border-bottom:0!important}
  .tcn-policy-benefit img{width:60px;height:60px}
  .tcn-policy-benefit strong{font-size:18px}
  .tcn-policy-benefit small{font-size:15px}
  .tcn-policy-note{padding:14px 16px;border-radius:16px}
  .tcn-policy-note p{font-size:14.5px}
}
@media(max-width:420px){
  .tcn-policy-card{grid-template-columns:1fr;text-align:center}
  .tcn-policy-card-content h3:after{left:10%;width:80%}
  .tcn-policy-benefit{grid-template-columns:58px 1fr}
  .tcn-policy-benefit img{width:54px;height:54px}
}
@media(prefers-reduced-motion:reduce){
  .tcn-policy *,
  .tcn-policy *:before,
  .tcn-policy *:after{animation:none!important;transition:none!important}
}
/* THEME COLOR + PNG ICON OVERRIDE */
.tcn-policy{color:var(--tcn-text)}
.tcn-policy-eyebrow{color:var(--tcn-primary);border-color:rgba(11,91,181,.30)}
.tcn-policy-heading h2{color:var(--tcn-primary-dark)}
.tcn-policy-heading p{color:var(--tcn-text)}
.tcn-policy-title-line{background:linear-gradient(90deg,transparent,var(--tcn-primary) 24%,#2f8ee9 50%,var(--tcn-primary) 76%,transparent)}
.tcn-policy-card{
  border-color:rgba(11,91,181,.20);
  box-shadow:var(--tcn-shadow);
}
.tcn-policy-card:hover{
  border-color:rgba(11,91,181,.46);
  box-shadow:0 20px 46px rgba(9,53,102,.18);
}
.tcn-policy-icon{min-height:132px}
.tcn-policy-icon img{
  display:block;width:126px;height:126px;object-fit:contain;
  background:transparent;
  mix-blend-mode:multiply;
  filter:drop-shadow(0 10px 14px rgba(9,53,102,.16));
}
.tcn-policy-card-content h3{color:var(--tcn-primary)}
.tcn-policy-card-content h3:after{background:linear-gradient(90deg,var(--tcn-primary) 0 18%,rgba(11,91,181,.25) 18% 100%)}
.tcn-policy-card-content p{color:var(--tcn-text)}
.tcn-policy-card-content strong{color:var(--tcn-primary-dark)}
.tcn-policy-benefits,.tcn-policy-note{
  border-color:rgba(11,91,181,.22);
  box-shadow:var(--tcn-shadow);
}
.tcn-policy-benefit img{
  display:block;width:72px;height:72px;object-fit:contain;
  background:transparent;
  mix-blend-mode:multiply;
}
.tcn-policy-benefit strong{color:var(--tcn-primary-dark)}
.tcn-policy-benefit small,.tcn-policy-note p{color:var(--tcn-text)}
.tcn-policy-note-icon{background:linear-gradient(145deg,#2387e8,var(--tcn-primary))}
.tcn-policy-note strong{color:var(--tcn-primary-dark)}
@media(max-width:720px){
  .tcn-policy-icon{min-height:auto}
  .tcn-policy-icon img{width:94px;height:94px}
  .tcn-policy-benefit img{width:62px;height:62px}
}
/* ========================================
   SECTION 5 - LOAN CALCULATOR
======================================== */
.tcn-calculator{
  position:relative;
  overflow:hidden;
  padding:88px 0 92px;
  background:
    linear-gradient(
      135deg,
      #f7faff 0%,
      #ffffff 50%,
      #eef6ff 100%
    );
}
/* ========================================
   HEADING
======================================== */
.tcn-calc-heading{
  max-width:1000px;
  margin:0 auto 48px;
  text-align:center;
}
.tcn-calc-eyebrow{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  margin-bottom:14px;
  padding:8px 18px;
  background:#fff2d1;
  color:#9c6000;
  border-radius:999px;
  font-size:17px;
  line-height:1;
  font-weight:800;
  text-transform:uppercase;
}
.tcn-calc-title-wrap{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:28px;
}
.tcn-calc-line{
  width:90px;
  height:2px;
  background:#174da8;
}
.tcn-calc-heading h2{
  margin:0;
  color:#123a8f;
  font-size:50px;
  line-height:1.1;
  font-weight:800;
  letter-spacing:-1px;
}
.tcn-calc-accent{
  display:block;
  width:76px;
  height:4px;
  margin:17px auto 18px;
  background:#f59e0b;
  border-radius:999px;
}
.tcn-calc-heading p{
  max-width:720px;
  margin:0 auto;
  color:#667085;
  font-size:19px;
  line-height:1.7;
}
/* ========================================
   MAIN LAYOUT
======================================== */
.tcn-calc-layout{
  position:relative;
  display:grid;
  grid-template-columns:
    minmax(0,1.75fr)
    minmax(280px,.72fr)
    minmax(300px,.9fr);
  align-items:stretch;
  gap:20px;
}
/* ========================================
   CALCULATOR BOX
======================================== */
.tcn-calc-box{
  position:relative;
  padding:28px;
  background:rgba(255,255,255,.98);
  border:1px solid #dbe5f2;
  border-radius:18px;
  box-shadow:
    0 18px 50px rgba(11,91,181,.10);
}
.tcn-calc-section-title{
  margin-bottom:18px;
  color:#123a8f;
  font-size:19px;
  line-height:1.3;
  font-weight:800;
}
/* ========================================
   LOAN TYPES
======================================== */
.tcn-calc-types{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:14px;
}
.tcn-calc-type{
  position:relative;
  min-height:145px;
  padding:12px 10px 16px;
  overflow:hidden;
  background:#fff;
  border:1px solid #dbe4ef;
  border-radius:12px;
  cursor:pointer;
  transition:
    transform .25s ease,
    border-color .25s ease,
    box-shadow .25s ease,
    background .25s ease;
}
.tcn-calc-type:hover{
  transform:translateY(-4px);
  border-color:#1767d2;
  box-shadow:
    0 10px 25px rgba(11,91,181,.13);
}
.tcn-calc-type.active{
  border:2px solid #1767d2;
  background:#f7faff;
  box-shadow:
    0 10px 25px rgba(11,91,181,.12);
}
.tcn-calc-type.active:after{
  content:"✓";
  position:absolute;
  top:8px;
  right:8px;
  width:25px;
  height:25px;
  display:flex;
  align-items:center;
  justify-content:center;
  background:#1767d2;
  color:#fff;
  border-radius:50%;
  font-size:14px;
  font-weight:800;
}
.tcn-calc-type-img{
  display:block;
  width:100%;
  height:75px;
  margin-bottom:9px;
  overflow:hidden;
  border-radius:8px;
}
.tcn-calc-type-img img{
  display:block;
  width:100%;
  height:100%;
  object-fit:cover;
  transition:transform .35s ease;
}
.tcn-calc-type:hover img{
  transform:scale(1.07);
}
.tcn-calc-type strong{
  display:block;
  color:#123a8f;
  font-size:15px;
  line-height:1.35;
  font-weight:800;
  text-align:center;
}
/* ========================================
   CONTROLS
======================================== */
.tcn-calc-controls{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:26px 40px;
  margin-top:26px;
  padding-top:24px;
  border-top:1px solid #e1e8f0;
}
.tcn-calc-control-full{
  grid-column:1 / -1;
}
.tcn-calc-control-head{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:15px;
  margin-bottom:14px;
}
.tcn-calc-control-head label{
  color:#123a8f;
  font-size:16px;
  font-weight:800;
}
.tcn-calc-control-head strong{
  color:#174da8;
  font-size:22px;
  line-height:1;
  font-weight:800;
}
/* ========================================
   RANGE
======================================== */
.tcn-calc-range{
  --range-progress:30%;
  width:100%;
  height:6px;
  margin:4px 0 10px;
  appearance:none;
  -webkit-appearance:none;
  outline:none;
  border-radius:999px;
  background:
    linear-gradient(
      to right,
      #1767d2 0%,
      #1767d2 var(--range-progress),
      #dce4ee var(--range-progress),
      #dce4ee 100%
    );
  cursor:pointer;
}
.tcn-calc-range::-webkit-slider-thumb{
  width:20px;
  height:20px;
  appearance:none;
  -webkit-appearance:none;
  background:#fff;
  border:3px solid #1767d2;
  border-radius:50%;
  box-shadow:
    0 3px 8px rgba(11,91,181,.20);
  cursor:pointer;
  transition:
    transform .2s ease,
    box-shadow .2s ease;
}
.tcn-calc-range::-webkit-slider-thumb:hover{
  transform:scale(1.15);
  box-shadow:
    0 4px 12px rgba(11,91,181,.28);
}
.tcn-calc-range::-moz-range-thumb{
  width:16px;
  height:16px;
  background:#fff;
  border:3px solid #1767d2;
  border-radius:50%;
  cursor:pointer;
}
.tcn-calc-minmax{
  display:flex;
  justify-content:space-between;
  gap:15px;
  color:#344054;
  font-size:13px;
  line-height:1.4;
}
/* ========================================
   BUTTON
======================================== */
.tcn-calc-submit{
  width:55%;
  min-height:56px;
  margin:28px auto 0;
  padding:0 26px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:20px;
  background:
    linear-gradient(
      135deg,
      #073f80 0%,
      #0759cb 100%
    );
  color:#fff;
  border:0;
  border-radius:10px;
  font-size:16px;
  font-weight:800;
  cursor:pointer;
  box-shadow:
    0 10px 25px rgba(11,91,181,.20);
  transition:
    transform .2s ease,
    box-shadow .2s ease;
}
.tcn-calc-submit:hover{
  transform:translateY(-3px);
  box-shadow:
    0 15px 30px rgba(11,91,181,.28);
}
.tcn-calc-submit-arrow{
  font-size:21px;
  transition:transform .2s ease;
}
.tcn-calc-submit:hover .tcn-calc-submit-arrow{
  transform:translateX(5px);
}
/* ========================================
   RESULT
======================================== */
.tcn-calc-result{
  padding:32px 28px;
  background:rgba(255,255,255,.97);
  border:1px solid #dbe5f2;
  border-radius:18px;
  box-shadow:
    0 18px 50px rgba(11,91,181,.10);
}
.tcn-calc-result h3{
  margin:0 0 25px;
  color:#123a8f;
  font-size:22px;
  line-height:1.3;
  font-weight:800;
}
.tcn-calc-result-item{
  padding:0 0 22px;
  margin-bottom:22px;
  border-bottom:1px solid #e1e8f0;
}
.tcn-calc-result-item span{
  display:block;
  margin-bottom:8px;
  color:#344054;
  font-size:16px;
}
.tcn-calc-result-item strong{
  display:block;
  color:#174da8;
  font-size:27px;
  line-height:1.2;
  font-weight:800;
}
.tcn-calc-monthly{
  margin-top:4px;
  padding:20px;
  background:
    linear-gradient(
      135deg,
      #f1f6ff,
      #e6efff
    );
  border-radius:12px;
}
.tcn-calc-monthly span{
  display:block;
  margin-bottom:8px;
  color:#344054;
  font-size:15px;
}
.tcn-calc-monthly strong{
  display:block;
  color:#123a8f;
  font-size:30px;
  line-height:1.15;
  font-weight:800;
}
.tcn-calc-note{
  display:flex;
  gap:10px;
  margin-top:22px;
}
.tcn-calc-note > span{
  flex:0 0 20px;
  width:20px;
  height:20px;
  display:flex;
  align-items:center;
  justify-content:center;
  background:#1767d2;
  color:#fff;
  border-radius:50%;
  font-size:12px;
  font-weight:800;
}
.tcn-calc-note p{
  margin:0;
  color:#475467;
  font-size:13px;
  line-height:1.55;
}
/* ========================================
   VISUAL
======================================== */
.tcn-calc-visual{
  position:relative;
  min-height:100%;
  overflow:hidden;
  border-radius:18px;
  box-shadow:
    0 18px 50px rgba(11,91,181,.10);
}
.tcn-calc-visual img{
  display:block;
  width:100%;
  height:100%;
  object-fit:cover;
  object-position:center;
  transition:transform .8s ease;
}
.tcn-calc-visual:hover img{
  transform:scale(1.035);
}
/* ========================================
   SCROLL ANIMATION
======================================== */
.tcn-calc-reveal{
  opacity:0;
  transform:translateY(30px);
  transition:
    opacity .7s ease,
    transform .7s ease;
}
.tcn-calc-reveal.is-visible{
  opacity:1;
  transform:translateY(0);
}
.tcn-calc-layout .tcn-calc-reveal:nth-child(2){
  transition-delay:.12s;
}
.tcn-calc-layout .tcn-calc-reveal:nth-child(3){
  transition-delay:.22s;
}
/* Result animation */
.tcn-calc-result.is-calculating strong{
  animation:tcnResultPulse .4s ease;
}
@keyframes tcnResultPulse{
  0%{
    transform:scale(1);
  }
  50%{
    transform:scale(1.05);
    color:#f59e0b;
  }
  100%{
    transform:scale(1);
  }
}
/* ========================================
   LAPTOP
======================================== */
@media(max-width:1350px){
  .tcn-calc-layout{
    grid-template-columns:
      minmax(0,1.65fr)
      minmax(270px,.7fr)
      minmax(260px,.75fr);
  }
  .tcn-calc-heading h2{
    font-size:46px;
  }
  .tcn-calc-box{
    padding:24px;
  }
  .tcn-calc-type{
    min-height:135px;
  }
}
/* ========================================
   TABLET
======================================== */
@media(max-width:1100px){
  .tcn-calc-layout{
    grid-template-columns:minmax(0,1fr) 330px;
  }
  .tcn-calc-visual{
    grid-column:1 / -1;
    height:360px;
  }
}
@media(max-width:850px){
  .tcn-calculator{
    padding:65px 0;
  }
  .tcn-calc-heading h2{
    font-size:39px;
  }
  .tcn-calc-line{
    width:50px;
  }
  .tcn-calc-layout{
    grid-template-columns:1fr;
  }
  .tcn-calc-result,
  .tcn-calc-visual{
    grid-column:1;
  }
  .tcn-calc-visual{
    height:340px;
  }
}
/* ========================================
   MOBILE
======================================== */
@media(max-width:600px){
  .tcn-calculator{
    padding:52px 0;
  }
  .tcn-calc-heading{
    margin-bottom:34px;
  }
  .tcn-calc-eyebrow{
    font-size:14px;
  }
  .tcn-calc-title-wrap{
    gap:12px;
  }
  .tcn-calc-line{
    width:25px;
  }
  .tcn-calc-heading h2{
    font-size:31px;
  }
  .tcn-calc-heading p{
    font-size:16px;
  }
  .tcn-calc-box{
    padding:18px 14px;
  }
  .tcn-calc-types{
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:10px;
  }
  .tcn-calc-type{
    min-height:130px;
  }
  .tcn-calc-type strong{
    font-size:13px;
  }
  .tcn-calc-controls{
    grid-template-columns:1fr;
    gap:25px;
  }
  .tcn-calc-control-full{
    grid-column:1;
  }
  .tcn-calc-control-head strong{
    font-size:19px;
  }
  .tcn-calc-submit{
    width:100%;
  }
  .tcn-calc-result{
    padding:25px 20px;
  }
  .tcn-calc-result-item strong{
    font-size:24px;
  }
  .tcn-calc-monthly strong{
    font-size:28px;
  }
  .tcn-calc-visual{
    height:280px;
  }
}
/* SECTION 6 - PROCESS */
.tcn-process{position:relative;overflow:hidden;padding:86px 0 78px;background:radial-gradient(circle at 50% 30%,rgba(255,255,255,.98),rgba(239,247,255,.88) 64%,rgba(218,237,255,.9)),none center/cover no-repeat}
.tcn-process:before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(255,255,255,.08),rgba(255,255,255,.32));pointer-events:none}.tcn-process-container{position:relative;z-index:2;max-width:1450px}
.tcn-process-heading{text-align:center;margin:0 auto 42px}.tcn-process-eyebrow{display:inline-flex;padding:11px 28px;border-radius:999px;background:linear-gradient(135deg,var(--tcn-primary),#126bd3);box-shadow:0 10px 24px rgba(11,91,181,.18);color:#fff;font-size:19px;font-weight:800}
.tcn-process-title-row{display:flex;align-items:center;justify-content:center;gap:24px;margin:13px 0 4px}.tcn-process-title-row i{width:74px;height:2px;background:linear-gradient(90deg,transparent,var(--tcn-secondary))}.tcn-process-title-row i:last-child{background:linear-gradient(90deg,var(--tcn-secondary),transparent)}
.tcn-process-title-row h2{margin:0;color:var(--tcn-primary-dark);font-size:clamp(42px,4vw,62px);line-height:1.08;font-weight:900;letter-spacing:-1.5px}.tcn-process-title-row h2 em{color:var(--tcn-secondary);font-style:normal}.tcn-process-heading>p{margin:12px 0 0;color:#203b68;font-size:21px;line-height:1.55}
.tcn-process-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px;position:relative}.tcn-process-card{position:relative;min-height:440px;padding:34px 25px 31px;border:1px solid rgba(11,91,181,.13);border-radius:28px;background:rgba(255,255,255,.95);box-shadow:0 16px 38px rgba(9,53,102,.12);text-align:center;overflow:hidden;transition:.35s}
.tcn-process-card:hover{transform:translateY(-10px);border-color:rgba(11,91,181,.34);box-shadow:0 25px 52px rgba(9,53,102,.19)}.tcn-process-number{position:absolute;left:22px;top:12px;color:rgba(11,91,181,.28);font-size:76px;line-height:1;font-weight:900;text-shadow:0 2px 8px rgba(11,91,181,.08)}
.tcn-process-icon{position:relative;display:grid;place-items:center;width:158px;height:158px;margin:30px auto 27px;border-radius:50%;background:linear-gradient(145deg,#1675df,var(--tcn-primary-dark));border:10px solid #e6f2ff;box-shadow:0 12px 25px rgba(11,91,181,.22);color:#fff;animation:tcnProcessFloat 4s ease-in-out infinite}.tcn-process-icon>span{font-size:65px;font-weight:800}.tcn-process-icon>b{position:absolute;right:-7px;bottom:9px;display:grid;place-items:center;min-width:43px;height:43px;padding:0 8px;border-radius:50%;background:var(--tcn-secondary);border:4px solid #fff;color:#fff;font-size:17px}
.tcn-process-card h3{margin:0;color:var(--tcn-primary-dark);font-size:23px;line-height:1.3;font-weight:900}.tcn-process-divider{display:block;width:48px;height:3px;margin:15px auto 17px;border-radius:4px;background:var(--tcn-secondary)}.tcn-process-card p{margin:0 auto;max-width:275px;color:#263c63;font-size:19px;line-height:1.68;font-weight:500}
.tcn-process-arrow{position:absolute;z-index:5;top:190px;display:grid;place-items:center;width:44px;height:44px;border-radius:50%;background:linear-gradient(145deg,#1677df,var(--tcn-primary));border:5px solid #e7f3ff;color:#fff;font-size:36px;box-shadow:0 8px 20px rgba(11,91,181,.22);animation:tcnProcessArrow 2.2s ease-in-out infinite}.tcn-process-arrow:nth-of-type(1){left:calc(25% - 22px)}.tcn-process-arrow:nth-of-type(2){left:calc(50% - 22px)}.tcn-process-arrow:nth-of-type(3){left:calc(75% - 22px)}
.tcn-process-benefits{display:grid;grid-template-columns:repeat(4,1fr);margin-top:36px;padding:24px 28px;border-radius:27px;background:linear-gradient(120deg,var(--tcn-primary-dark),var(--tcn-primary) 55%,#126bd3);box-shadow:0 20px 42px rgba(7,63,128,.22)}.tcn-process-benefit{display:flex;align-items:center;justify-content:center;gap:16px;min-height:92px;padding:8px 24px;border-right:1px solid rgba(255,255,255,.28);transition:.3s}.tcn-process-benefit:last-child{border-right:0}.tcn-process-benefit:hover{transform:translateY(-4px)}.tcn-process-benefit>span{flex:0 0 58px;display:grid;place-items:center;width:58px;height:58px;border:2px solid #fff;border-radius:50%;color:#fff;font-size:28px;font-weight:900}.tcn-process-benefit strong{display:block;color:#ffc13d;font-size:19px}.tcn-process-benefit p{margin:3px 0 0;color:#fff;font-size:16px;line-height:1.45}
@keyframes tcnProcessArrow{50%{transform:translateX(6px)}}@keyframes tcnProcessReveal{from{opacity:0;transform:translateY(28px)}to{opacity:1;transform:none}}@keyframes tcnProcessFloat{50%{transform:translateY(-7px)}}.tcn-process-reveal{animation:tcnProcessReveal .8s cubic-bezier(.2,.75,.3,1) both;animation-delay:var(--delay,0s)}
@media(max-width:1100px){.tcn-process-grid{grid-template-columns:repeat(2,1fr)}.tcn-process-arrow{display:none}.tcn-process-benefits{grid-template-columns:repeat(2,1fr)}.tcn-process-benefit:nth-child(2){border-right:0}}
@media(max-width:680px){.tcn-process{padding:64px 0 56px}.tcn-process-eyebrow{font-size:15px}.tcn-process-title-row{gap:10px}.tcn-process-title-row i{width:28px}.tcn-process-title-row h2{font-size:36px}.tcn-process-heading>p{font-size:17px}.tcn-process-grid{grid-template-columns:1fr}.tcn-process-card{min-height:auto}.tcn-process-card p{font-size:18px}.tcn-process-benefits{grid-template-columns:1fr;padding:16px 20px}.tcn-process-benefit{justify-content:flex-start;border-right:0;border-bottom:1px solid rgba(255,255,255,.22);padding:16px 8px}.tcn-process-benefit:last-child{border-bottom:0}}
@media(prefers-reduced-motion:reduce){.tcn-process *{animation:none!important;transition:none!important}}
/* ========================================
   STATS STRIP - SỐ LIỆU NỔI BẬT
======================================== */
.tcn-stats{
  position:relative;
  overflow:hidden;
  padding:52px 0;
  background:
    radial-gradient(circle at 15% 10%, rgba(20,104,210,.28), transparent 34%),
    radial-gradient(circle at 85% 90%, rgba(0,87,184,.22), transparent 32%),
    linear-gradient(135deg, var(--tcn-primary-dark) 0%, #0a3f7d 48%, #082f63 100%);
}
.tcn-stats::before{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  background:
    linear-gradient(115deg, transparent 0 30%, rgba(255,255,255,.04) 44%, transparent 58%),
    radial-gradient(circle at 50% 50%, rgba(255,255,255,.04), transparent 60%);
}
.tcn-stats .container{
  position:relative;
  z-index:2;
}
.tcn-stats-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  align-items:stretch;
}
.tcn-stat-item{
  position:relative;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  min-height:170px;
  padding:18px 32px;
  text-align:center;
  opacity:0;
  transform:translateY(24px);
  animation:tcnStatReveal .75s cubic-bezier(.2,.75,.3,1) forwards;
}
.tcn-stat-item:nth-child(1){animation-delay:.05s}
.tcn-stat-item:nth-child(2){animation-delay:.16s}
.tcn-stat-item:nth-child(3){animation-delay:.27s}
.tcn-stat-item:nth-child(4){animation-delay:.38s}
.tcn-stat-item:not(:last-child)::after{
  content:"";
  position:absolute;
  right:0;
  top:16%;
  width:1px;
  height:68%;
  background:linear-gradient(
    180deg,
    transparent,
    rgba(255,255,255,.20) 18%,
    rgba(255,255,255,.20) 82%,
    transparent
  );
}
.tcn-stat-icon{
  display:grid;
  place-items:center;
  width:72px;
  height:72px;
  margin-bottom:14px;
  border-radius:50%;
  border:2px solid rgba(100,160,255,.65);
  background:linear-gradient(145deg,#1b67cf,#0e3f93);
  box-shadow:
    0 10px 24px rgba(0,0,0,.16),
    inset 0 0 18px rgba(255,255,255,.10);
  color:#fff;
  font-size:30px;
  font-weight:800;
  animation:tcnStatFloat 3.6s ease-in-out infinite;
}
.tcn-stat-item:nth-child(2) .tcn-stat-icon{animation-delay:.3s}
.tcn-stat-item:nth-child(3) .tcn-stat-icon{animation-delay:.6s}
.tcn-stat-item:nth-child(4) .tcn-stat-icon{animation-delay:.9s}
.tcn-stat-number{
  display:block;
  margin:0 0 6px;
  color:#ffc45e;
  font-size:clamp(38px,3.5vw,58px);
  line-height:1;
  font-weight:900;
  letter-spacing:-1.5px;
  text-shadow:0 3px 12px rgba(0,0,0,.15);
}
.tcn-stat-label{
  margin:0;
  color:#fff;
  font-size:18px;
  line-height:1.45;
  font-weight:600;
  opacity:.94;
}
/* Hover */
.tcn-stat-item{
  transition:transform .32s ease, background-color .32s ease;
}
.tcn-stat-item:hover{
  transform:translateY(-5px);
}
.tcn-stat-item:hover .tcn-stat-icon{
  box-shadow:
    0 14px 28px rgba(0,0,0,.20),
    0 0 0 8px rgba(255,255,255,.05),
    inset 0 0 18px rgba(255,255,255,.12);
}
.tcn-stat-item:hover .tcn-stat-number{
  animation:tcnStatPulse .55s ease;
}
/* Animations */
@keyframes tcnStatReveal{
  from{
    opacity:0;
    transform:translateY(24px);
  }
  to{
    opacity:1;
    transform:translateY(0);
  }
}
@keyframes tcnStatFloat{
  0%,100%{
    transform:translateY(0);
  }
  50%{
    transform:translateY(-6px);
  }
}
@keyframes tcnStatPulse{
  0%,100%{transform:scale(1)}
  50%{transform:scale(1.08)}
}
/* Responsive */
@media(max-width:992px){
  .tcn-stats{
    padding:38px 0;
  }
  .tcn-stats-grid{
    grid-template-columns:repeat(2,1fr);
  }
  .tcn-stat-item{
    min-height:155px;
  }
  .tcn-stat-item:nth-child(2)::after{
    display:none;
  }
  .tcn-stat-item:nth-child(1),
  .tcn-stat-item:nth-child(2){
    border-bottom:1px solid rgba(255,255,255,.12);
  }
  .tcn-stat-number{
    font-size:42px;
  }
  .tcn-stat-label{
    font-size:17px;
  }
}
@media(max-width:560px){
  .tcn-stats{
    padding:28px 0;
  }
  .tcn-stats-grid{
    grid-template-columns:1fr;
  }
  .tcn-stat-item{
    min-height:auto;
    padding:24px 18px;
  }
  .tcn-stat-item::after{
    display:none!important;
  }
  .tcn-stat-item:not(:last-child){
    border-bottom:1px solid rgba(255,255,255,.12);
  }
  .tcn-stat-icon{
    width:64px;
    height:64px;
    font-size:26px;
  }
  .tcn-stat-number{
    font-size:38px;
  }
  .tcn-stat-label{
    font-size:16px;
  }
}
@media(prefers-reduced-motion:reduce){
  .tcn-stats *,
  .tcn-stats *::before,
  .tcn-stats *::after{
    animation:none!important;
    transition:none!important;
  }
}
/* Counter number animation */
.tcn-stat-number{
  min-width:120px;
  font-variant-numeric:tabular-nums;
  will-change:transform;
}
.tcn-stat-number.is-counted{
  animation:tcnCountFinish .48s cubic-bezier(.2,.8,.3,1);
}
@keyframes tcnCountFinish{
  0%,100%{transform:scale(1)}
  52%{transform:scale(1.10)}
}
/* ========================================
   SECTION 7 - TESTIMONIALS
======================================== */
.tcn-testimonials{
  position:relative;
  overflow:hidden;
  padding:88px 0 76px;
  background:
    radial-gradient(circle at 50% 0%,rgba(11,91,181,.08),transparent 38%),
    linear-gradient(180deg,#f8fbff 0%,#fff 58%,#f7faff 100%);
}
.tcn-testimonial-heading{
  max-width:1100px;
  margin:0 auto 48px;
  text-align:center;
}
.tcn-testimonial-eyebrow{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-height:42px;
  padding:0 22px;
  margin-bottom:14px;
  color:#a86600;
  background:#fff7e6;
  border:1px solid #f4b23d;
  border-radius:12px;
  font-size:18px;
  line-height:1;
  font-weight:800;
  letter-spacing:.3px;
  text-transform:uppercase;
}
.tcn-testimonial-title-wrap{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:28px;
}
.tcn-testimonial-line{
  width:95px;
  height:2px;
  background:#174da8;
}
.tcn-testimonial-heading h2{
  margin:0;
  color:#123a8f;
  font-size:48px;
  line-height:1.12;
  font-weight:800;
  letter-spacing:-1px;
}
.tcn-testimonial-accent{
  display:block;
  width:76px;
  height:4px;
  margin:16px auto 18px;
  background:#f59e0b;
  border-radius:999px;
}
.tcn-testimonial-heading p{
  max-width:780px;
  margin:0 auto;
  color:#667085;
  font-size:19px;
  line-height:1.7;
}
/* Slider */
.tcn-testimonial-slider{
  position:relative;
}
.tcn-testimonial-viewport{
  overflow:hidden;
  margin:0 -8px;
  padding:8px;
}
.tcn-testimonial-track{
  display:flex;
  gap:24px;
  transition:transform .55s cubic-bezier(.22,.61,.36,1);
  will-change:transform;
}
.tcn-testimonial-card{
  flex:0 0 calc((100% - 48px) / 3);
  min-width:0;
  display:flex;
  flex-direction:column;
  padding:28px;
  background:#fff;
  border:1px solid #e1e9f3;
  border-radius:20px;
  box-shadow:0 14px 38px rgba(8,44,87,.08);
  transition:transform .28s ease,box-shadow .28s ease,border-color .28s ease;
}
.tcn-testimonial-card:hover{
  transform:translateY(-6px);
  border-color:#c8d9f0;
  box-shadow:0 20px 46px rgba(8,44,87,.13);
}
.tcn-testimonial-user{
  display:flex;
  align-items:center;
  gap:16px;
}
.tcn-testimonial-user strong{
  display:block;
  margin-bottom:5px;
  color:#123a8f;
  font-size:20px;
  line-height:1.25;
  font-weight:800;
}
.tcn-testimonial-user span{
  display:block;
  color:#667085;
  font-size:15px;
  line-height:1.4;
}
.tcn-testimonial-stars{
  margin-top:8px;
  color:#f5a000;
  font-size:22px;
  line-height:1;
  letter-spacing:2px;
}
.tcn-testimonial-quote{
  position:relative;
  flex:1;
  min-height:190px;
  margin:26px 0 4px;
  padding:10px 8px 0 20px;
}
.tcn-testimonial-quote p{
  margin:0;
  color:#344054;
  font-size:17px;
  line-height:1.75;
}
.tcn-quote-mark{
  position:absolute;
  left:0;
  top:-8px;
  color:#0b5bb5;
  font-size:44px;
  line-height:1;
  font-weight:800;
}
.tcn-quote-mark-end{
  left:auto;
  right:0;
  top:auto;
  bottom:-12px;
}
/* Controls */
.tcn-testimonial-controls{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:22px;
  margin-top:30px;
}
.tcn-testimonial-arrow{
  width:48px;
  height:48px;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:0;
  background:#fff;
  color:#174da8;
  border:1px solid #cfd9e8;
  border-radius:50%;
  font-size:32px;
  line-height:1;
  cursor:pointer;
  box-shadow:0 8px 20px rgba(8,44,87,.06);
  transition:background .2s ease,color .2s ease,border-color .2s ease,transform .2s ease;
}
.tcn-testimonial-arrow:hover{
  transform:translateY(-2px);
  background:#0b5bb5;
  color:#fff;
  border-color:#0b5bb5;
}
.tcn-testimonial-dots{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
}
.tcn-testimonial-dot{
  width:10px;
  height:10px;
  padding:0;
  border:0;
  border-radius:50%;
  background:#d6dee9;
  cursor:pointer;
  transition:width .22s ease,background .22s ease,border-radius .22s ease;
}
.tcn-testimonial-dot.active{
  width:28px;
  border-radius:999px;
  background:#0b5bb5;
}
/* Reveal animation */
.tcn-testimonial-reveal{
  opacity:0;
  transform:translateY(30px);
  transition:opacity .7s ease,transform .7s ease;
}
.tcn-testimonial-reveal.is-visible{
  opacity:1;
  transform:translateY(0);
}
.tcn-testimonial-slider.tcn-testimonial-reveal{
  transition-delay:.12s;
}
.tcn-testimonial-card{
  opacity:0;
  transform:translateY(22px);
}
.tcn-testimonial-slider.is-visible .tcn-testimonial-card{
  animation:tcnTestimonialCardIn .55s ease forwards;
}
.tcn-testimonial-slider.is-visible .tcn-testimonial-card:nth-child(2){animation-delay:.08s}
.tcn-testimonial-slider.is-visible .tcn-testimonial-card:nth-child(3){animation-delay:.16s}
.tcn-testimonial-slider.is-visible .tcn-testimonial-card:nth-child(4){animation-delay:.24s}
.tcn-testimonial-slider.is-visible .tcn-testimonial-card:nth-child(5){animation-delay:.32s}
.tcn-testimonial-slider.is-visible .tcn-testimonial-card:nth-child(6){animation-delay:.40s}
@keyframes tcnTestimonialCardIn{
  to{
    opacity:1;
    transform:translateY(0);
  }
}
/* Laptop */
@media(max-width:1200px){
  .tcn-testimonial-heading h2{font-size:42px}
  .tcn-testimonial-line{width:70px}
  .tcn-testimonial-card{padding:24px}
  .tcn-testimonial-user strong{font-size:18px}
  .tcn-testimonial-quote p{font-size:16px}
}
/* Tablet */
@media(max-width:900px){
  .tcn-testimonials{padding:70px 0 64px}
  .tcn-testimonial-heading h2{font-size:38px}
  .tcn-testimonial-line{width:45px}
  .tcn-testimonial-card{flex-basis:calc((100% - 24px) / 2)}
}
/* Mobile */
@media(max-width:600px){
  .tcn-testimonials{padding:54px 0}
  .tcn-testimonial-heading{margin-bottom:34px}
  .tcn-testimonial-eyebrow{font-size:15px;min-height:38px;padding:0 17px}
  .tcn-testimonial-title-wrap{gap:12px}
  .tcn-testimonial-line{width:24px}
  .tcn-testimonial-heading h2{font-size:31px}
  .tcn-testimonial-heading p{font-size:16px}
  .tcn-testimonial-card{flex-basis:100%;padding:22px}
  .tcn-testimonial-user>img{width:68px;height:68px;flex-basis:68px}
  .tcn-testimonial-user strong{font-size:18px}
  .tcn-testimonial-stars{font-size:20px}
  .tcn-testimonial-quote{min-height:155px}
  .tcn-testimonial-quote p{font-size:16px}
  .tcn-testimonial-photo{height:210px}
  .tcn-testimonial-controls{gap:16px;margin-top:24px}
  .tcn-testimonial-arrow{width:44px;height:44px}
}
@media(prefers-reduced-motion:reduce){
  .tcn-testimonial-track,
  .tcn-testimonial-card,
  .tcn-testimonial-reveal,
  .tcn-testimonial-photo img{
    transition:none!important;
    animation:none!important;
  }
  .tcn-testimonial-reveal,
  .tcn-testimonial-card{
    opacity:1!important;
    transform:none!important;
  }
}
/* ========================================
   SECTION FAQ - CÂU HỎI THƯỜNG GẶP
======================================== */
.tcn-faq{position:relative;overflow:hidden;padding:78px 0 82px;background:linear-gradient(180deg,#fbfdff 0%,#f3f8ff 100%);color:var(--tcn-text)}
.tcn-faq:after{content:"";position:absolute;left:-5%;right:-5%;bottom:-88px;height:150px;border-radius:50% 50% 0 0;background:linear-gradient(90deg,var(--tcn-primary),#2f83e9);opacity:.98;z-index:0}
.tcn-faq-inner{position:relative;z-index:2}
.tcn-faq-decor{position:absolute;width:270px;height:270px;border-radius:50%;pointer-events:none;opacity:.55;filter:blur(1px)}
.tcn-faq-decor-left{left:-120px;top:110px;background:radial-gradient(circle,rgba(11,91,181,.12) 0 3px,transparent 4px) 0 0/18px 18px}
.tcn-faq-decor-right{right:-110px;top:10px;background:radial-gradient(circle,rgba(11,91,181,.14) 0 3px,transparent 4px) 0 0/18px 18px}
.tcn-faq-heading{text-align:center;max-width:900px;margin:0 auto 42px}
.tcn-faq-eyebrow{display:inline-flex;align-items:center;justify-content:center;min-height:42px;padding:8px 28px;border-radius:999px;background:linear-gradient(135deg,#ffc729,var(--tcn-secondary));color:#172033;font-size:15px;font-weight:800;letter-spacing:.04em;box-shadow:0 8px 22px rgba(245,158,11,.22)}
.tcn-faq-heading h2{margin:17px 0 12px;font-size:clamp(30px,3vw,47px);line-height:1.13;letter-spacing:-.02em;color:#101b2d;font-weight:850}
.tcn-faq-heading h2 strong{color:var(--tcn-primary);font-weight:850}
.tcn-faq-heading p{margin:0;color:var(--tcn-muted);font-size:17px;line-height:1.75}
.tcn-faq-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px 14px}
.tcn-faq-item{background:#fff;border:1px solid rgba(11,91,181,.17);border-radius:14px;box-shadow:0 8px 24px rgba(21,73,133,.055);overflow:hidden;transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease}
.tcn-faq-item:hover{transform:translateY(-2px);border-color:rgba(11,91,181,.35);box-shadow:0 13px 30px rgba(21,73,133,.10)}
.tcn-faq-item.is-open{border-color:rgba(11,91,181,.44);box-shadow:0 14px 34px rgba(21,73,133,.12)}
.tcn-faq-question{width:100%;min-height:92px;border:0;background:transparent;padding:14px 16px;display:grid;grid-template-columns:48px 44px minmax(0,1fr) 18px;gap:11px;align-items:center;text-align:left;cursor:pointer;color:var(--tcn-text);font:inherit}
.tcn-faq-number{width:45px;height:45px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(145deg,var(--tcn-primary),#064795);color:#fff;font-size:17px;font-weight:800;box-shadow:0 7px 16px rgba(11,91,181,.20)}
.tcn-faq-icon{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:#edf5ff;color:#1971d4;font-weight:800;font-size:24px;line-height:1}
.tcn-faq-question-text{font-size:15.5px;line-height:1.45;font-weight:750}
.tcn-faq-chevron{width:10px;height:10px;border-right:2px solid var(--tcn-primary);border-bottom:2px solid var(--tcn-primary);transform:rotate(45deg) translateY(-3px);transition:transform .25s ease}
.tcn-faq-item.is-open .tcn-faq-chevron{transform:rotate(225deg) translate(-2px,-2px)}
.tcn-faq-answer{border-top:1px solid #edf2f8;background:#fbfdff}
.tcn-faq-answer-inner{padding:0 18px 19px 119px;color:#58677a;font-size:14.5px;line-height:1.7}
.tcn-faq-answer-inner:before{content:"";display:block;height:14px}
.tcn-faq-cta{position:relative;z-index:3;margin-top:25px;padding:18px 22px;display:grid;grid-template-columns:1.2fr 1fr auto;gap:25px;align-items:center;background:rgba(255,255,255,.98);border:1px solid rgba(11,91,181,.17);border-radius:16px;box-shadow:0 16px 38px rgba(14,65,122,.12)}
.tcn-faq-brand,.tcn-faq-contact{display:flex;align-items:center;gap:14px}
.tcn-faq-brand{padding-right:24px;border-right:1px solid #dfe9f5}
.tcn-faq-shield{width:58px;height:66px;display:grid;place-items:center;flex:0 0 auto;background:linear-gradient(145deg,#2c83e6,#0851ab);clip-path:polygon(50% 0,92% 16%,86% 74%,50% 100%,14% 74%,8% 16%);color:#fff;font-size:28px;font-weight:900;filter:drop-shadow(0 7px 10px rgba(11,91,181,.22))}
.tcn-faq-brand div,.tcn-faq-contact div{display:flex;flex-direction:column;gap:3px}
.tcn-faq-brand strong{font-size:20px;color:#142037}
.tcn-faq-brand span,.tcn-faq-contact span{font-size:14px;color:#5b6878}
.tcn-faq-phone-icon{width:50px;height:50px;border-radius:50%;display:grid;place-items:center;background:#eaf4ff;color:var(--tcn-primary);font-size:22px;border:1px solid #d4e7fb}
.tcn-faq-contact strong{font-size:27px;letter-spacing:.02em;color:var(--tcn-primary);line-height:1.1}
.tcn-faq-cta-btn{display:inline-flex;align-items:center;justify-content:center;gap:16px;min-height:58px;padding:0 25px;border-radius:10px;background:linear-gradient(135deg,#ffb416,var(--tcn-secondary));color:#172033;font-weight:850;font-size:15px;white-space:nowrap;box-shadow:0 10px 22px rgba(245,158,11,.24);transition:transform .2s ease,box-shadow .2s ease}
.tcn-faq-cta-btn:hover{color:#172033;transform:translateY(-2px);box-shadow:0 14px 27px rgba(245,158,11,.30)}
.tcn-faq-cta-btn span{font-size:23px;line-height:1}
@media (max-width:1050px){.tcn-faq-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.tcn-faq-cta{grid-template-columns:1fr 1fr}.tcn-faq-cta-btn{grid-column:1/-1}.tcn-faq-brand{border-right:0}.tcn-faq:after{bottom:-105px}}
@media (max-width:700px){.tcn-faq{padding:58px 0 70px}.tcn-faq-heading{margin-bottom:30px}.tcn-faq-heading h2{font-size:30px}.tcn-faq-heading p{font-size:15px}.tcn-faq-grid{grid-template-columns:1fr;gap:10px}.tcn-faq-question{min-height:82px;grid-template-columns:42px 38px minmax(0,1fr) 15px;gap:9px;padding:12px}.tcn-faq-number{width:40px;height:40px;font-size:15px}.tcn-faq-icon{width:36px;height:36px;font-size:21px}.tcn-faq-question-text{font-size:14.5px}.tcn-faq-answer-inner{padding:0 15px 17px 101px;font-size:14px}.tcn-faq-cta{grid-template-columns:1fr;gap:16px;padding:18px}.tcn-faq-brand{padding:0}.tcn-faq-contact{padding-top:15px;border-top:1px solid #e3ebf5}.tcn-faq-contact strong{font-size:23px}.tcn-faq-cta-btn{grid-column:auto;width:100%}.tcn-faq:after{height:115px;bottom:-80px}}
/* ========================================
   SECTION 8 - ĐĂNG KÝ TƯ VẤN
======================================== */
.tcn-consultation{
  scroll-margin-top:110px;
  position:relative;
  isolation:isolate;
  overflow:hidden;
  min-height:760px;
  padding:56px 0 62px;
  background:#064aa6;
  color:#fff;
}
.tcn-consultation-bg{
  position:absolute;
  inset:0;
  z-index:-3;
  background:none center/cover no-repeat;
}
.tcn-consultation-overlay{
  position:absolute;
  inset:0;
  z-index:-2;
  background:linear-gradient(
    90deg,
    rgba(4,60,143,.96) 0%,
    rgba(5,76,178,.90) 48%,
    rgba(4,64,145,.24) 69%,
    rgba(4,44,101,.03) 100%
  );
}
.tcn-consultation-inner{
  position:relative;
}
/* ========================================
   HEADING
======================================== */
.tcn-consultation-heading{
  width:min(760px,64%);
  margin:0 0 26px;
  text-align:center;
}
.tcn-consultation-eyebrow{
  display:inline-flex;
  align-items:center;
  gap:10px;
  margin-bottom:14px;
  padding:9px 20px;
  border:1px solid #f7b12a;
  border-radius:13px;
  background:linear-gradient(180deg,#fff8e4,#ffedbd);
  box-shadow:0 5px 15px rgba(3,44,102,.12);
  color:#9a5700;
  font-size:17px;
  font-weight:800;
  letter-spacing:.2px;
}
.tcn-consultation-eyebrow:before{
  content:'☎';
  color:#f59e0b;
  font-size:21px;
}
.tcn-consultation-heading h2{
  margin:0;
  color:#fff;
  font-size:48px;
  line-height:1.08;
  font-weight:850;
  letter-spacing:-1.1px;
  text-shadow:0 3px 10px rgba(0,38,93,.16);
}
.tcn-consultation-heading h2 strong{
  color:#ffb20c;
  font-weight:850;
}
.tcn-consultation-heading p{
  max-width:650px;
  margin:18px auto 0;
  color:rgba(255,255,255,.96);
  font-size:19px;
  line-height:1.65;
}
/* ========================================
   LAYOUT
======================================== */
.tcn-consultation-layout{
  display:grid;
  grid-template-columns:minmax(0,820px) 255px 1fr;
  align-items:center;
  gap:18px;
}
/* ========================================
   FORM
======================================== */
.tcn-consultation-form{
  position:relative;
  padding:30px 30px 27px;
  border:1px solid rgba(255,255,255,.78);
  border-radius:22px;
  background:rgba(255,255,255,.98);
  box-shadow:0 24px 65px rgba(0,38,96,.24);
}
.tcn-form-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:18px 20px;
}
/* ========================================
   FIELD
======================================== */
.tcn-field{
  position:relative;
  display:flex;
  align-items:center;
  min-height:66px;
  margin:0;
  border:1px solid #ccd8ea;
  border-radius:10px;
  background:#fff;
  transition:
    border-color .25s,
    box-shadow .25s,
    transform .25s;
}
.tcn-field:focus-within{
  border-color:#1766d6;
  box-shadow:
    0 0 0 4px rgba(23,102,214,.10);
  transform:translateY(-1px);
}
.tcn-field-full{
  grid-column:1/-1;
}
/* ========================================
   FIELD ICON
======================================== */
.tcn-field-icon{
  flex:0 0 56px;
  color:#075ed1;
  font-size:26px;
  font-weight:700;
  text-align:center;
}
/* ========================================
   INPUT / SELECT / TEXTAREA
   FONT ĐÃ TĂNG
======================================== */
.tcn-field input,
.tcn-field select,
.tcn-field textarea{
  width:100%;
  min-width:0;
  margin:0;
  padding:0 18px 0 0;
  border:0!important;
  outline:0!important;
  background:transparent!important;
  box-shadow:none!important;
  color:#263754;
  font-family:inherit;
  /* tăng từ 17px */
  font-size:18px;
  font-weight:500;
  line-height:1.5;
}
/* Placeholder */
.tcn-field input::placeholder,
.tcn-field textarea::placeholder{
  color:#687894;
  opacity:1;
  font-size:18px;
  font-weight:500;
}
/* SELECT */
.tcn-field select{
  height:64px;
  cursor:pointer;
  color:#687894;
  font-size:18px;
  font-weight:500;
}
/* ========================================
   TEXTAREA
======================================== */
.tcn-field-textarea{
  align-items:flex-start;
  min-height:126px;
}
.tcn-field-textarea .tcn-field-icon{
  padding-top:19px;
}
.tcn-field textarea{
  min-height:124px;
  padding-top:19px;
  font-size:18px;
  resize:vertical;
}
/* ========================================
   CONSENT / CHECKBOX
======================================== */
.tcn-consent{
  display:flex;
  align-items:flex-start;
  gap:11px;
  margin:20px 0 22px;
  color:#33425c;
  /* tăng từ 15px */
  font-size:16px;
  font-weight:500;
  line-height:1.55;
  cursor:pointer;
}
.tcn-consent input{
  position:absolute;
  opacity:0;
  pointer-events:none;
}
.tcn-consent-box{
  display:flex;
  flex:0 0 24px;
  width:24px;
  height:24px;
  align-items:center;
  justify-content:center;
  border:2px solid #0d62d5;
  border-radius:4px;
  background:#fff;
  color:transparent;
  font-size:16px;
  font-weight:900;
}
.tcn-consent input:checked + .tcn-consent-box{
  background:#0d62d5;
  color:#fff;
}
.tcn-consent a{
  color:#075ed1;
  font-weight:700;
  text-decoration:none;
}
/* ========================================
   SUBMIT BUTTON
======================================== */
.tcn-consult-submit{
  position:relative;
  overflow:hidden;
  width:100%;
  min-height:64px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:30px;
  border:0;
  border-radius:9px;
  background:linear-gradient(
    100deg,
    #073fb4,
    #0871e6
  );
  box-shadow:
    0 12px 24px rgba(8,83,189,.20);
  color:#fff;
  /* tăng từ 20px */
  font-size:21px;
  font-weight:850;
  letter-spacing:.2px;
  cursor:pointer;
  transition:
    transform .25s,
    box-shadow .25s;
}
.tcn-consult-submit:before{
  content:'';
  position:absolute;
  top:-80%;
  left:-25%;
  width:18%;
  height:260%;
  background:rgba(255,255,255,.25);
  transform:rotate(20deg);
  transition:left .6s ease;
}
.tcn-consult-submit:hover{
  transform:translateY(-2px);
  box-shadow:
    0 16px 30px rgba(8,83,189,.30);
}
.tcn-consult-submit:hover:before{
  left:115%;
}
.tcn-submit-arrow{
  font-size:31px;
  font-weight:400;
  transition:transform .25s;
}
.tcn-consult-submit:hover .tcn-submit-arrow{
  transform:translateX(7px);
}
/* ========================================
   SUCCESS MESSAGE
======================================== */
.tcn-form-success{
  margin-bottom:18px;
  padding:13px 16px;
  border-radius:9px;
  background:#e9f8ef;
  color:#17713b;
  font-size:16px;
  font-weight:700;
}
/* ========================================
   BENEFITS
======================================== */
.tcn-consultation-benefits{
  grid-column:2;
  display:flex;
  flex-direction:column;
  gap:20px;
}
.tcn-consult-benefit{
  display:flex;
  align-items:center;
  gap:13px;
  min-height:94px;
  padding:16px 15px;
  border:1px solid rgba(255,255,255,.8);
  border-radius:13px;
  background:rgba(255,255,255,.96);
  box-shadow:
    0 12px 30px rgba(0,42,100,.18);
  color:#123a8f;
  transition:
    transform .25s,
    box-shadow .25s;
}
.tcn-consult-benefit:hover{
  transform:translateX(5px);
  box-shadow:
    0 17px 35px rgba(0,42,100,.24);
}
.tcn-benefit-symbol{
  display:flex;
  flex:0 0 52px;
  width:52px;
  height:52px;
  align-items:center;
  justify-content:center;
  border-radius:50%;
  background:#e8f3ff;
  color:#0867db;
  font-size:27px;
  font-weight:800;
}
.tcn-consult-benefit strong,
.tcn-consult-benefit small{
  display:block;
}
.tcn-consult-benefit strong{
  margin-bottom:5px;
  /* tăng từ 13px */
  font-size:15px;
  line-height:1.3;
  font-weight:850;
}
.tcn-consult-benefit small{
  color:#344054;
  /* tăng từ 12px */
  font-size:13px;
  line-height:1.45;
}
/* ========================================
   REVEAL ANIMATION
======================================== */
.tcn-consult-reveal{
  opacity:0;
  transform:translateY(28px);
  transition:
    opacity .7s ease,
    transform .7s cubic-bezier(.2,.7,.2,1);
}
.tcn-consultation.is-visible .tcn-consult-reveal{
  opacity:1;
  transform:none;
}
.tcn-consultation.is-visible .tcn-consultation-form{
  transition-delay:.12s;
}
.tcn-consultation.is-visible
.tcn-consult-benefit:nth-child(1){
  transition-delay:.2s;
}
.tcn-consultation.is-visible
.tcn-consult-benefit:nth-child(2){
  transition-delay:.3s;
}
.tcn-consultation.is-visible
.tcn-consult-benefit:nth-child(3){
  transition-delay:.4s;
}
/* ========================================
   LAPTOP
======================================== */
@media(max-width:1200px){
  .tcn-consultation-heading{
    width:70%;
  }
  .tcn-consultation-heading h2{
    font-size:43px;
  }
  .tcn-consultation-layout{
    grid-template-columns:minmax(0,1fr) 240px;
  }
  .tcn-consultation-benefits{
    grid-column:2;
  }
  .tcn-consultation-form{
    grid-column:1;
  }
  .tcn-consultation-bg{
    background-position:65% center;
  }
}
/* ========================================
   TABLET
======================================== */
@media(max-width:900px){
  .tcn-consultation{
    padding:50px 0;
  }
  .tcn-consultation-overlay{
    background:rgba(4,66,155,.88);
  }
  .tcn-consultation-heading{
    width:100%;
    max-width:760px;
    margin-left:auto;
    margin-right:auto;
  }
  .tcn-consultation-layout{
    grid-template-columns:1fr;
  }
  .tcn-consultation-form,
  .tcn-consultation-benefits{
    grid-column:1;
  }
  .tcn-consultation-benefits{
    display:grid;
    grid-template-columns:repeat(3,1fr);
  }
  .tcn-consult-benefit{
    min-height:115px;
    flex-direction:column;
    text-align:center;
  }
  .tcn-consultation-bg{
    background-position:70% center;
  }
}
/* ========================================
   MOBILE
======================================== */
@media(max-width:650px){
  .tcn-consultation-heading h2{
    font-size:34px;
  }
  .tcn-consultation-heading p{
    font-size:16px;
  }
  .tcn-consultation-eyebrow{
    font-size:14px;
  }
  .tcn-consultation-form{
    padding:22px 18px;
    border-radius:17px;
  }
  .tcn-form-grid{
    grid-template-columns:1fr;
    gap:13px;
  }
  .tcn-field-full{
    grid-column:1;
  }
  .tcn-field{
    min-height:60px;
  }
  .tcn-field-icon{
    flex-basis:50px;
    font-size:23px;
  }
  .tcn-field select{
    height:58px;
  }
  /* Mobile giữ 16px để không quá lớn */
  .tcn-field input,
  .tcn-field select,
  .tcn-field textarea{
    font-size:16px;
  }
  .tcn-field input::placeholder,
  .tcn-field textarea::placeholder{
    font-size:16px;
  }
  .tcn-consultation-benefits{
    grid-template-columns:1fr;
  }
  .tcn-consult-benefit{
    min-height:auto;
    flex-direction:row;
    text-align:left;
  }
  .tcn-consult-benefit strong{
    font-size:15px;
  }
  .tcn-consult-benefit small{
    font-size:13px;
  }
  .tcn-consult-submit{
    min-height:60px;
    font-size:18px;
  }
  .tcn-consent{
    font-size:14px;
  }
}
/* ========================================
   REDUCE MOTION
======================================== */
@media(prefers-reduced-motion:reduce){
  .tcn-consult-reveal{
    opacity:1;
    transform:none;
    transition:none;
  }
  .tcn-consult-submit:before{
    display:none;
  }
}
