/* === V19 CLEAN TESTIMONIAL AUTOPLAY === */
#testimonials,
#testimonials .tcn-testimonial-heading,
#testimonials .tcn-testimonial-slider,
#testimonials .tcn-testimonial-viewport,
#testimonials .tcn-testimonial-track,
#testimonials .tcn-testimonial-card{
  opacity:1!important;
  visibility:visible!important;
}
#testimonials .tcn-testimonial-reveal{
  opacity:1!important;
  visibility:visible!important;
  transform:none!important;
}
#testimonials .tcn-css-slider{
  position:relative!important;
}
#testimonials .tcn-slide-radio{
  position:absolute!important;
  width:1px!important;
  height:1px!important;
  opacity:0!important;
  pointer-events:none!important;
}
#testimonials .tcn-testimonial-viewport{
  width:100%!important;
  overflow:hidden!important;
}
#testimonials .tcn-testimonial-track{
  display:flex!important;
  gap:24px!important;
  width:100%!important;
  overflow:visible!important;
  will-change:transform!important;
  animation:tcnAutoDesktop 25s linear infinite!important;
}
#testimonials .tcn-testimonial-card{
  flex:0 0 calc((100% - 48px)/3)!important;
  min-width:0!important;
  opacity:1!important;
  visibility:visible!important;
  transform:none!important;
  animation:none!important;
}
#testimonials .tcn-testimonial-controls{
  display:none!important;
}
/* 5 seconds at each useful desktop position */
@keyframes tcnAutoDesktop{
  0%,18%{transform:translateX(0)}
  20%,38%{transform:translateX(calc(-1 * ((100% - 48px)/3 + 24px)))}
  40%,58%{transform:translateX(calc(-2 * ((100% - 48px)/3 + 24px)))}
  60%,78%{transform:translateX(calc(-3 * ((100% - 48px)/3 + 24px)))}
  80%,100%{transform:translateX(0)}
}
@media(max-width:900px){
  #testimonials .tcn-testimonial-track{
    animation-name:tcnAutoTablet!important;
    animation-duration:30s!important;
  }
  #testimonials .tcn-testimonial-card{
    flex-basis:calc((100% - 24px)/2)!important;
  }
  @keyframes tcnAutoTablet{
    0%,14%{transform:translateX(0)}
    16%,30%{transform:translateX(calc(-1 * ((100% - 24px)/2 + 24px)))}
    32%,46%{transform:translateX(calc(-2 * ((100% - 24px)/2 + 24px)))}
    48%,62%{transform:translateX(calc(-3 * ((100% - 24px)/2 + 24px)))}
    64%,78%{transform:translateX(calc(-4 * ((100% - 24px)/2 + 24px)))}
    80%,100%{transform:translateX(0)}
  }
}
@media(max-width:600px){
  #testimonials .tcn-testimonial-track{
    animation-name:tcnAutoMobile!important;
    animation-duration:35s!important;
  }
  #testimonials .tcn-testimonial-card{
    flex-basis:100%!important;
  }
  @keyframes tcnAutoMobile{
    0%,11%{transform:translateX(0)}
    13%,24%{transform:translateX(calc(-1 * (100% + 24px)))}
    26%,37%{transform:translateX(calc(-2 * (100% + 24px)))}
    39%,50%{transform:translateX(calc(-3 * (100% + 24px)))}
    52%,63%{transform:translateX(calc(-4 * (100% + 24px)))}
    65%,76%{transform:translateX(calc(-5 * (100% + 24px)))}
    78%,100%{transform:translateX(0)}
  }
}
/* === V20 TESTIMONIAL ARROWS + DOTS === */
#testimonials .tcn-testimonial-controls{
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  margin-top:28px!important;
  min-height:52px!important;
}
#testimonials .tcn-css-controls{
  display:none!important;
  align-items:center!important;
  justify-content:center!important;
  gap:18px!important;
}
/* If autoplay is running and no radio is selected, show controls for slide 1 */
#testimonials .tcn-css-controls-1{
  display:flex!important;
}
/* Once user clicks a control, show only the matching control set */
#tcn-slide-1:checked ~ .tcn-testimonial-controls .tcn-css-controls,
#tcn-slide-2:checked ~ .tcn-testimonial-controls .tcn-css-controls,
#tcn-slide-3:checked ~ .tcn-testimonial-controls .tcn-css-controls,
#tcn-slide-4:checked ~ .tcn-testimonial-controls .tcn-css-controls,
#tcn-slide-5:checked ~ .tcn-testimonial-controls .tcn-css-controls,
#tcn-slide-6:checked ~ .tcn-testimonial-controls .tcn-css-controls{
  display:none!important;
}
#tcn-slide-1:checked ~ .tcn-testimonial-controls .tcn-css-controls-1,
#tcn-slide-2:checked ~ .tcn-testimonial-controls .tcn-css-controls-2,
#tcn-slide-3:checked ~ .tcn-testimonial-controls .tcn-css-controls-3,
#tcn-slide-4:checked ~ .tcn-testimonial-controls .tcn-css-controls-4,
#tcn-slide-5:checked ~ .tcn-testimonial-controls .tcn-css-controls-5,
#tcn-slide-6:checked ~ .tcn-testimonial-controls .tcn-css-controls-6{
  display:flex!important;
}
#testimonials .tcn-testimonial-arrow{
  width:46px!important;
  height:46px!important;
  border-radius:50%!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  background:#ffffff!important;
  border:1px solid #dbe5f0!important;
  box-shadow:0 6px 18px rgba(9,53,102,.12)!important;
  color:#0b5bb5!important;
  font-size:30px!important;
  font-weight:700!important;
  line-height:1!important;
  cursor:pointer!important;
  user-select:none!important;
  transition:transform .2s ease,box-shadow .2s ease,background .2s ease!important;
}
#testimonials .tcn-testimonial-arrow:hover{
  transform:translateY(-2px)!important;
  box-shadow:0 9px 22px rgba(9,53,102,.18)!important;
  background:#f5f9ff!important;
}
#testimonials .tcn-testimonial-dots{
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  gap:9px!important;
}
#testimonials .tcn-testimonial-dot{
  display:block!important;
  width:10px!important;
  height:10px!important;
  border-radius:50%!important;
  background:#cbd8e8!important;
  border:0!important;
  cursor:pointer!important;
  transition:width .2s ease,background .2s ease,transform .2s ease!important;
}
#tcn-slide-1:checked ~ .tcn-testimonial-controls .tcn-css-controls-1 .tcn-testimonial-dot:nth-child(1),
#tcn-slide-2:checked ~ .tcn-testimonial-controls .tcn-css-controls-2 .tcn-testimonial-dot:nth-child(2),
#tcn-slide-3:checked ~ .tcn-testimonial-controls .tcn-css-controls-3 .tcn-testimonial-dot:nth-child(3),
#tcn-slide-4:checked ~ .tcn-testimonial-controls .tcn-css-controls-4 .tcn-testimonial-dot:nth-child(4),
#tcn-slide-5:checked ~ .tcn-testimonial-controls .tcn-css-controls-5 .tcn-testimonial-dot:nth-child(5),
#tcn-slide-6:checked ~ .tcn-testimonial-controls .tcn-css-controls-6 .tcn-testimonial-dot:nth-child(6){
  background:#0b5bb5!important;
  transform:scale(1.25)!important;
}
/* Default visual state while autoplay has not been manually overridden */
#testimonials .tcn-css-controls-1 .tcn-testimonial-dot:first-child{
  background:#0b5bb5;
}
@media(max-width:600px){
  #testimonials .tcn-testimonial-controls{margin-top:20px!important}
  #testimonials .tcn-testimonial-arrow{
    width:42px!important;height:42px!important;font-size:27px!important;
  }
  #testimonials .tcn-testimonial-dot{width:9px!important;height:9px!important}
}
/* Manual click overrides autoplay */
#tcn-slide-1:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track,
#tcn-slide-2:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track,
#tcn-slide-3:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track,
#tcn-slide-4:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track,
#tcn-slide-5:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track,
#tcn-slide-6:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{
  animation:none!important;
}
#tcn-slide-1:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(0)!important}
#tcn-slide-2:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-1 * ((100% - 48px)/3 + 24px)))!important}
#tcn-slide-3:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-2 * ((100% - 48px)/3 + 24px)))!important}
#tcn-slide-4:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track,
#tcn-slide-5:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track,
#tcn-slide-6:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-3 * ((100% - 48px)/3 + 24px)))!important}
@media(max-width:900px){
  #tcn-slide-2:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-1 * ((100% - 24px)/2 + 24px)))!important}
  #tcn-slide-3:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-2 * ((100% - 24px)/2 + 24px)))!important}
  #tcn-slide-4:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-3 * ((100% - 24px)/2 + 24px)))!important}
  #tcn-slide-5:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track,
  #tcn-slide-6:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-4 * ((100% - 24px)/2 + 24px)))!important}
}
@media(max-width:600px){
  #tcn-slide-2:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-1 * (100% + 24px)))!important}
  #tcn-slide-3:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-2 * (100% + 24px)))!important}
  #tcn-slide-4:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-3 * (100% + 24px)))!important}
  #tcn-slide-5:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-4 * (100% + 24px)))!important}
  #tcn-slide-6:checked ~ .tcn-testimonial-viewport .tcn-testimonial-track{transform:translateX(calc(-5 * (100% + 24px)))!important}
}
/* === V23 ORIGINAL CALCULATOR RANGE === */
.tcn-calc-range{
  --range-progress:30%;
  width:100%!important;
  height:6px!important;
  margin:4px 0 10px!important;
  appearance:none!important;
  -webkit-appearance:none!important;
  outline:none!important;
  border-radius:999px!important;
  background:linear-gradient(
    to right,
    #1767d2 0%,
    #1767d2 var(--range-progress),
    #dce4ee var(--range-progress),
    #dce4ee 100%
  )!important;
  cursor:pointer!important;
}
.tcn-calc-range::-webkit-slider-runnable-track{
  height:6px!important;
  background:transparent!important;
  border:0!important;
}
.tcn-calc-range::-webkit-slider-thumb{
  width:20px!important;
  height:20px!important;
  margin-top:-7px!important;
  appearance:none!important;
  -webkit-appearance:none!important;
  background:#fff!important;
  border:3px solid #1767d2!important;
  border-radius:50%!important;
  box-shadow:0 3px 8px rgba(11,91,181,.20)!important;
  cursor:pointer!important;
}
.tcn-calc-range::-moz-range-track{
  height:6px!important;
  background:transparent!important;
}
.tcn-calc-range::-moz-range-progress{
  height:6px!important;
  background:#1767d2!important;
  border-radius:999px!important;
}
.tcn-calc-range::-moz-range-thumb{
  width:16px!important;
  height:16px!important;
  background:#fff!important;
  border:3px solid #1767d2!important;
  border-radius:50%!important;
  cursor:pointer!important;
}
/* === V24 DIRECT RANGE CALCULATOR === */
.tcn-calc-range{
  background:#dce4ee;
}
/* === V26 LOAN TYPE BUTTONS === */
.tcn-calc-type{cursor:pointer!important}
.tcn-calc-type.active{
  background:#0b5bb5!important;
  border-color:#0b5bb5!important;
  color:#fff!important;
  box-shadow:0 8px 18px rgba(11,91,181,.18)!important;
}
/* === V27 LOAN TYPE ACTIVE DESIGN === */
.tcn-calc-type{
  position:relative!important;
  overflow:hidden!important;
  background:#fff!important;
  color:#173b72!important;
  border:1.5px solid #d8e3ef!important;
  border-radius:16px!important;
  box-shadow:0 5px 14px rgba(9,53,102,.06)!important;
  transition:border-color .22s ease,box-shadow .22s ease,transform .22s ease,background .22s ease!important;
}
.tcn-calc-type:hover{
  border-color:#9fc2ea!important;
  box-shadow:0 9px 22px rgba(11,91,181,.10)!important;
  transform:translateY(-2px)!important;
}
.tcn-calc-type.active{
  background:#fff!important;
  color:#0b4ea2!important;
  border:2px solid #0b5bb5!important;
  box-shadow:0 10px 26px rgba(11,91,181,.16)!important;
  transform:translateY(-2px)!important;
}
.tcn-calc-type.active:after{
  content:"✓"!important;
  position:absolute!important;
  top:9px!important;
  right:9px!important;
  width:26px!important;
  height:26px!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  border-radius:50%!important;
  background:#0b5bb5!important;
  color:#fff!important;
  font-size:15px!important;
  font-weight:700!important;
  line-height:1!important;
  box-shadow:0 4px 10px rgba(11,91,181,.25)!important;
  z-index:5!important;
}
.tcn-calc-type-img{
  display:block!important;
  overflow:hidden!important;
  border-radius:12px!important;
  margin-bottom:12px!important;
  background:#f4f8fd!important;
}
.tcn-calc-type-img img{
  width:100%!important;
  height:82px!important;
  object-fit:cover!important;
  border-radius:12px!important;
  transition:transform .25s ease!important;
}
.tcn-calc-type:hover .tcn-calc-type-img img,
.tcn-calc-type.active .tcn-calc-type-img img{
  transform:scale(1.025)!important;
}
.tcn-calc-type span:last-child,
.tcn-calc-type strong,
.tcn-calc-type-title{
  color:inherit!important;
}
.tcn-calc-type.active .tcn-calc-type-title,
.tcn-calc-type.active strong{
  color:#0b4ea2!important;
}
/* === V28 FULL IMAGE CLEAN LOAN TYPE === */
.tcn-calc-type.active:after{
  content:none!important;
  display:none!important;
}
.tcn-calc-type-img{
  display:block!important;
  width:100%!important;
  height:auto!important;
  overflow:hidden!important;
  border-radius:12px!important;
  background:#f4f8fd!important;
  margin:0 0 12px!important;
}
.tcn-calc-type-img img{
  display:block!important;
  width:100%!important;
  height:auto!important;
  aspect-ratio:1/1!important;
  object-fit:contain!important;
  object-position:center!important;
  border-radius:12px!important;
  transform:none!important;
  transition:none!important;
}
.tcn-calc-type:hover .tcn-calc-type-img img,
.tcn-calc-type.active .tcn-calc-type-img img{
  transform:none!important;
}
.tcn-calc-type{
  padding:10px!important;
}
.tcn-calc-type strong{
  display:block!important;
  margin-top:2px!important;
  line-height:1.35!important;
}
/* === V29 CONSULT FORM EMAIL === */
.tcn-form-status{
  display:none;
  margin-top:12px;
  padding:11px 14px;
  border-radius:10px;
  font-size:14px;
  font-weight:600;
}
.tcn-form-status.is-sending{
  display:block;
  color:#174b87;
  background:#eef6ff;
}
.tcn-form-status.is-success{
  display:block;
  color:#176b3a;
  background:#edf9f1;
}
/* === V30 FORM CONSENT + VALIDATION FIX === */
.tcn-consent{
  display:flex!important;
  align-items:flex-start!important;
  gap:10px!important;
  margin:16px 0 14px!important;
  color:#fff!important;
  font-size:14px!important;
  line-height:1.5!important;
}
.tcn-consent input[type="checkbox"]{
  -webkit-appearance:none!important;
  appearance:none!important;
  width:22px!important;
  height:22px!important;
  min-width:22px!important;
  margin:0!important;
  border:2px solid rgba(255,255,255,.95)!important;
  border-radius:5px!important;
  background:#fff!important;
  cursor:pointer!important;
  position:relative!important;
  box-shadow:0 2px 8px rgba(0,0,0,.12)!important;
}
.tcn-consent input[type="checkbox"]:checked{
  background:#f59e0b!important;
  border-color:#f59e0b!important;
}
.tcn-consent input[type="checkbox"]:checked:after{
  content:"✓"!important;
  position:absolute!important;
  inset:0!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  color:#fff!important;
  font-size:15px!important;
  font-weight:800!important;
}
.tcn-consent label,.tcn-consent span,.tcn-consent a{color:#fff!important}
.tcn-consent a{text-decoration:underline!important;font-weight:600!important}
.tcn-consent.is-error input[type="checkbox"]{
  border-color:#ffd166!important;
  box-shadow:0 0 0 3px rgba(255,209,102,.22)!important;
}
.tcn-form-error{
  display:none;
  margin:0 0 12px!important;
  padding:10px 13px!important;
  border-radius:9px!important;
  background:#fff4e5!important;
  color:#9a4b00!important;
  font-size:14px!important;
  font-weight:600!important;
}
.tcn-form-error.is-visible{display:block!important}
/* === V31 CALCULATOR IMAGE UNDER RESULT === */
.tcn-calc-right{
  display:flex!important;
  flex-direction:column!important;
  gap:20px!important;
  min-width:0!important;
}
.tcn-calc-right .tcn-calc-result{
  width:100%!important;
  margin:0!important;
}
.tcn-calc-right .tcn-calc-visual{
  width:100%!important;
  margin:0!important;
  overflow:hidden!important;
  border-radius:18px!important;
}
.tcn-calc-right .tcn-calc-visual img{
  display:block!important;
  width:100%!important;
  height:auto!important;
  object-fit:cover!important;
  border-radius:18px!important;
}
/* Calculator now uses two main columns: controls + result/image */
.tcn-calculator-grid,
.tcn-calc-grid,
.tcn-calculator-inner{
  grid-template-columns:minmax(0,1.45fr) minmax(300px,.75fr)!important;
}
@media(max-width:900px){
  .tcn-calculator-grid,
  .tcn-calc-grid,
  .tcn-calculator-inner{
    grid-template-columns:1fr!important;
  }
  .tcn-calc-right{
    width:100%!important;
  }
}
/* === V32 RESULT BACKGROUND IMAGE === */
.tcn-calc-right{display:block!important}
.tcn-calc-right .tcn-calc-result{
  position:relative!important;
  overflow:hidden!important;
  width:100%!important;
  min-height:520px!important;
  margin:0!important;
  padding:30px!important;
  border-radius:22px!important;
  background-image:
    linear-gradient(rgba(255,255,255,.90),rgba(255,255,255,.90)),
    url('data:image/webp;base64,')!important;
  background-size:cover!important;
  background-position:center!important;
  background-repeat:no-repeat!important;
  box-shadow:0 16px 40px rgba(9,53,102,.14)!important;
}
.tcn-calc-right .tcn-calc-result > *{
  position:relative!important;
  z-index:2!important;
}
@media(max-width:900px){
  .tcn-calc-right .tcn-calc-result{
    min-height:0!important;
    padding:24px!important;
  }
}
/* === V35 POLICY EYEBROW ICON FIX === */
.tcn-policy-info-icon{
  width:25px!important;
  height:25px!important;
  min-width:25px!important;
  display:block!important;
  color:#0b5bb5!important;
  flex:0 0 25px!important;
}
/* === V36 LOAN SOLUTION FULL IMAGE === */
.tcn-loan-image{
  height:auto!important;
  aspect-ratio:16/10!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  padding:0!important;
  background:#eef5ff!important;
}
.tcn-loan-image img{
  width:100%!important;
  height:100%!important;
  object-fit:contain!important;
  object-position:center!important;
  transform:none!important;
}
.tcn-loan-card:hover .tcn-loan-image img{
  transform:none!important;
}
/* === V36 FOOTER BACK TO TOP === */
.tcn-footer-top{
  position:absolute;
  right:28px;
  top:28px;
  z-index:8;
  width:50px;
  height:50px;
  display:flex;
  align-items:center;
  justify-content:center;
  border:1px solid rgba(255,255,255,.38);
  border-radius:50%;
  background:linear-gradient(135deg,#0b5bb5,#073f80);
  color:#fff!important;
  box-shadow:0 10px 24px rgba(0,20,55,.25);
  font-size:28px;
  line-height:1;
  font-weight:700;
  cursor:pointer;
  transition:transform .22s ease,box-shadow .22s ease,background .22s ease;
}
.tcn-footer-top:hover{
  transform:translateY(-4px);
  background:linear-gradient(135deg,#126bd3,#0b5bb5);
  box-shadow:0 14px 30px rgba(0,20,55,.32);
}
@media(max-width:700px){
  .tcn-footer-top{
    right:16px;
    top:18px;
    width:44px;
    height:44px;
    font-size:24px;
  }
}
/* === V36 CONSULT EYEBROW CLEAN === */
.tcn-consultation-eyebrow:before{content:none!important;display:none!important}
/* === V37 FOOTER ENTITY FIX === */
.tcn-footer-links a:before,
.tcn-footer-menu a:before,
.tcn-footer-col ul a:before{
  content:none!important;
  display:none!important;
}
.tcn-footer-links a,
.tcn-footer-menu a,
.tcn-footer-col ul a{
  padding-left:0!important;
}
