/* =========================================================
   V41 - MOBILE HEADER / PHONE / MENU FIX
========================================================= */
@media(max-width:768px){
  .tcn-header,
  .tcn-header-container{
    height:68px!important;
  }
  .tcn-header-container{
    width:calc(100% - 20px)!important;
    margin:0 auto!important;
    display:grid!important;
    grid-template-columns:minmax(118px,1fr) auto 44px!important;
    align-items:center!important;
    column-gap:8px!important;
    padding:0!important;
  }
  /* Logo: căn giữa trên/dưới */
  .tcn-logo{
    grid-column:1!important;
    height:68px!important;
    min-width:0!important;
    display:flex!important;
    align-items:center!important;
    justify-content:flex-start!important;
    margin:0!important;
    padding:0!important;
  }
  .tcn-logo > a{
    height:68px!important;
    display:flex!important;
    align-items:center!important;
    justify-content:flex-start!important;
    margin:0!important;
    padding:0!important;
  }
  .tcn-logo-image{
    display:block!important;
    width:145px!important;
    height:48px!important;
    max-width:145px!important;
    max-height:48px!important;
    margin:0!important;
    object-fit:contain!important;
    object-position:left center!important;
    vertical-align:middle!important;
  }
  /* Số điện thoại nằm giữa logo và nút menu */
  .tcn-hotline{
    grid-column:2!important;
    display:flex!important;
    align-items:center!important;
    justify-content:center!important;
    margin:0!important;
    min-width:0!important;
  }
  .tcn-hotline a{
    min-height:38px!important;
    padding:0 10px!important;
    gap:5px!important;
    border:1px solid rgba(255,255,255,.72)!important;
    border-radius:999px!important;
    background:rgba(255,255,255,.07)!important;
    color:#fff!important;
    font-size:12px!important;
    font-weight:800!important;
    white-space:nowrap!important;
  }
  .tcn-hotline-icon{
    font-size:14px!important;
  }
  /* Nút hamburger */
  .tcn-mobile-menu{
    grid-column:3!important;
    display:flex!important;
    flex-direction:column!important;
    align-items:center!important;
    justify-content:center!important;
    width:44px!important;
    height:44px!important;
    margin:0!important;
    padding:8px!important;
    border:1px solid rgba(255,255,255,.28)!important;
    border-radius:10px!important;
    background:rgba(255,255,255,.08)!important;
    cursor:pointer!important;
    position:relative!important;
    z-index:100001!important;
  }
  .tcn-mobile-menu span{
    display:block!important;
    width:24px!important;
    height:2px!important;
    margin:3px 0!important;
    border-radius:999px!important;
    background:#fff!important;
    transition:transform .25s ease,opacity .25s ease!important;
  }
  .tcn-mobile-menu.is-active span:nth-child(1){
    transform:translateY(8px) rotate(45deg)!important;
  }
  .tcn-mobile-menu.is-active span:nth-child(2){
    opacity:0!important;
  }
  .tcn-mobile-menu.is-active span:nth-child(3){
    transform:translateY(-8px) rotate(-45deg)!important;
  }
  /* Menu mobile: khi click phải hiện đầy đủ */
  .tcn-navigation{
    display:none!important;
    position:fixed!important;
    top:68px!important;
    left:0!important;
    right:0!important;
    width:100%!important;
    z-index:100000!important;
    max-height:calc(100vh - 68px)!important;
    overflow-y:auto!important;
    -webkit-overflow-scrolling:touch!important;
    padding:10px 18px 18px!important;
    background:linear-gradient(180deg,#063b7d,#052f67)!important;
    border-top:1px solid rgba(255,255,255,.12)!important;
    box-shadow:0 18px 30px rgba(0,28,65,.28)!important;
  }
  .tcn-navigation.is-open{
    display:block!important;
  }
  .tcn-menu{
    display:flex!important;
    flex-direction:column!important;
    align-items:stretch!important;
    justify-content:flex-start!important;
    width:100%!important;
    gap:0!important;
    margin:0!important;
    padding:0!important;
  }
  .tcn-menu li{
    width:100%!important;
    border-bottom:1px solid rgba(255,255,255,.10)!important;
  }
  .tcn-menu li:last-child{
    border-bottom:0!important;
  }
  .tcn-menu li a{
    display:flex!important;
    width:100%!important;
    min-height:0!important;
    padding:14px 4px!important;
    color:#fff!important;
    font-size:14px!important;
    line-height:1.35!important;
    font-weight:700!important;
    text-transform:uppercase!important;
  }
  .tcn-menu li a:hover,
  .tcn-menu li a:focus{
    color:#f5a000!important;
  }
  body.tcn-menu-open{
    overflow:hidden!important;
  }
}
@media(max-width:430px){
  .tcn-header-container{
    grid-template-columns:minmax(105px,1fr) auto 42px!important;
    width:calc(100% - 14px)!important;
    column-gap:5px!important;
  }
  .tcn-logo-image{
    width:126px!important;
    max-width:126px!important;
    height:44px!important;
    max-height:44px!important;
  }
  .tcn-hotline a{
    min-height:34px!important;
    padding:0 7px!important;
    font-size:10.5px!important;
  }
  .tcn-hotline-icon{
    font-size:12px!important;
  }
  .tcn-mobile-menu{
    width:42px!important;
    height:42px!important;
    padding:7px!important;
  }
}
/* =========================================================
   V42 - MOBILE MENU HARD FIX + REMOVE NEWS
========================================================= */
@media(max-width:768px){
  .tcn-navigation{
    display:block!important;
    position:fixed!important;
    top:68px!important;
    left:0!important;
    right:0!important;
    width:100%!important;
    z-index:100000!important;
    max-height:calc(100vh - 68px)!important;
    overflow-y:auto!important;
    -webkit-overflow-scrolling:touch!important;
    padding:10px 18px 18px!important;
    background:linear-gradient(180deg,#063b7d 0%,#052f67 100%)!important;
    border-top:1px solid rgba(255,255,255,.12)!important;
    box-shadow:0 18px 30px rgba(0,28,65,.28)!important;
    opacity:0!important;
    visibility:hidden!important;
    pointer-events:none!important;
    transform:translateY(-14px)!important;
    transition:
      opacity .22s ease,
      transform .22s ease,
      visibility .22s ease!important;
  }
  .tcn-navigation.is-open{
    opacity:1!important;
    visibility:visible!important;
    pointer-events:auto!important;
    transform:translateY(0)!important;
  }
  .tcn-menu{
    display:flex!important;
    flex-direction:column!important;
    align-items:stretch!important;
    justify-content:flex-start!important;
    width:100%!important;
    margin:0!important;
    padding:0!important;
    gap:0!important;
  }
  .tcn-menu li{
    display:block!important;
    width:100%!important;
    margin:0!important;
    padding:0!important;
    border-bottom:1px solid rgba(255,255,255,.11)!important;
  }
  .tcn-menu li:last-child{
    border-bottom:0!important;
  }
  .tcn-menu li a{
    display:flex!important;
    align-items:center!important;
    width:100%!important;
    min-height:50px!important;
    padding:0 4px!important;
    color:#fff!important;
    font-size:15px!important;
    line-height:1.3!important;
    font-weight:700!important;
    text-transform:uppercase!important;
    text-decoration:none!important;
  }
  .tcn-menu li a:hover,
  .tcn-menu li a:focus{
    color:#f5a000!important;
  }
  .tcn-mobile-menu{
    position:relative!important;
    z-index:100001!important;
  }
  .tcn-mobile-menu.is-active{
    background:rgba(255,255,255,.16)!important;
    border-color:rgba(255,255,255,.55)!important;
  }
  body.tcn-menu-open{
    overflow:hidden!important;
    touch-action:none!important;
  }
}
/* Desktop: đảm bảo không có Tin tức bị sinh lại từ pseudo/ẩn hiện */
/* Tin tuc menu is visible */
/* =========================================================
   V44 ABOUT US - SAFE VERSION
========================================================= */
.tcn-about-safe{
  position:relative;
  overflow:hidden;
  padding:78px 0 72px;
  background:linear-gradient(135deg,#f7fbff 0%,#fff 52%,#eef6ff 100%);
}
.tcn-about-safe-grid{
  display:grid;
  grid-template-columns:minmax(0,1.05fr) minmax(390px,.95fr);
  align-items:center;
  gap:42px;
}
.tcn-about-safe-copy{animation:tcnAboutSafeLeft .8s ease both}
.tcn-about-safe-eyebrow{
  display:block;color:#f59e0b;font-size:20px;font-weight:900;letter-spacing:.4px
}
.tcn-about-safe-line{
  display:block;width:48px;height:3px;margin:12px 0 22px;background:#f59e0b;border-radius:10px
}
.tcn-about-safe h2{
  margin:0 0 17px;color:#0a4b9e;font-size:clamp(40px,4vw,59px);line-height:1.05;font-weight:900;letter-spacing:-1.2px
}
.tcn-about-safe h3{
  margin:0 0 18px;max-width:680px;color:#172033;font-size:23px;line-height:1.48
}
.tcn-about-safe-copy>p{
  margin:0 0 25px;max-width:700px;color:#46556c;font-size:16.5px;line-height:1.72
}
.tcn-about-safe-features{display:grid;gap:15px}
.tcn-about-safe-features>div{
  display:grid;grid-template-columns:52px 1fr;align-items:center;gap:13px
}
.tcn-about-safe-features>div>b{
  width:48px;height:48px;display:grid;place-items:center;border-radius:50%;
  background:linear-gradient(145deg,#126bd3,#073f80);color:#fff;font-size:14px
}
.tcn-about-safe-features span{display:grid;gap:2px}
.tcn-about-safe-features strong{color:#0a4b9e;font-size:17px}
.tcn-about-safe-features small{color:#44536a;font-size:14px}
.tcn-about-safe-image{
  min-height:480px;overflow:hidden;border-radius:38% 18px 18px 38%;
  background:#eaf4ff;box-shadow:0 20px 48px rgba(8,54,113,.14);
  animation:tcnAboutSafeRight .85s ease both
}
.tcn-about-safe-image img{
  width:100%;height:100%;min-height:480px;display:block;object-fit:cover;object-position:center
}
.tcn-about-safe-stats{
  display:grid;grid-template-columns:repeat(4,minmax(0,1fr));
  margin-top:32px;padding:22px 16px;border-radius:18px;
  background:linear-gradient(135deg,#0a4da8,#075bbd 55%,#073f80);
  box-shadow:0 18px 40px rgba(5,54,119,.20);
  animation:tcnAboutSafeUp .9s .12s ease both
}
.tcn-about-safe-stat{
  display:grid;justify-items:center;text-align:center;gap:5px;padding:7px 14px;
  border-right:1px solid rgba(255,255,255,.20)
}
.tcn-about-safe-stat:last-child{border-right:0}
.tcn-about-safe-stat em{
  width:62px;height:62px;display:grid;place-items:center;border-radius:50%;
  border:4px solid rgba(255,255,255,.85);background:#eef7ff;color:#0756b6;
  font-style:normal;font-size:18px;font-weight:900
}
.tcn-about-counter{
  color:#ffc137;font-size:37px;line-height:1;font-weight:950;font-variant-numeric:tabular-nums
}
.tcn-about-safe-stat>b{color:#fff;font-size:14px}
.tcn-about-safe-stat small{color:rgba(255,255,255,.82);font-size:12px}
@keyframes tcnAboutSafeLeft{from{opacity:0;transform:translateX(-30px)}to{opacity:1;transform:none}}
@keyframes tcnAboutSafeRight{from{opacity:0;transform:translateX(30px)}to{opacity:1;transform:none}}
@keyframes tcnAboutSafeUp{from{opacity:0;transform:translateY(25px)}to{opacity:1;transform:none}}
@media(max-width:900px){
  .tcn-about-safe-grid{grid-template-columns:1fr;gap:25px}
  .tcn-about-safe-image{min-height:330px;border-radius:20px}
  .tcn-about-safe-image img{min-height:330px}
  .tcn-about-safe-stats{grid-template-columns:repeat(2,1fr)}
  .tcn-about-safe-stat{border-right:0;border-bottom:1px solid rgba(255,255,255,.16)}
  .tcn-about-safe-stat:nth-child(odd){border-right:1px solid rgba(255,255,255,.16)}
  .tcn-about-safe-stat:nth-last-child(-n+2){border-bottom:0}
}
@media(max-width:600px){
  .tcn-about-safe{padding:48px 0}
  .tcn-about-safe-eyebrow{font-size:15px}
  .tcn-about-safe h2{font-size:33px}
  .tcn-about-safe h3{font-size:18px}
  .tcn-about-safe-copy>p{font-size:14.5px}
  .tcn-about-safe-features strong{font-size:14.5px}
  .tcn-about-safe-features small{font-size:12.5px}
  .tcn-about-safe-image,.tcn-about-safe-image img{min-height:280px}
  .tcn-about-safe-stats{padding:10px}
  .tcn-about-safe-stat{padding:13px 5px}
  .tcn-about-safe-stat em{width:50px;height:50px;font-size:15px}
  .tcn-about-counter{font-size:27px}
  .tcn-about-safe-stat>b{font-size:11px}
  .tcn-about-safe-stat small{font-size:10px}
}
@media(prefers-reduced-motion:reduce){
  .tcn-about-safe-copy,.tcn-about-safe-image,.tcn-about-safe-stats{animation:none!important}
}
/* =========================================================
   V47 - ABOUT US CSS-ONLY ANIMATION + ODOMETER
   Không phụ thuộc JavaScript
========================================================= */
/* Luôn có chuyển động nhẹ để người dùng nhìn thấy animation */
.tcn-about-safe-copy{
  animation:tcnAboutFloatCopy 5s ease-in-out infinite!important;
}
.tcn-about-safe-image{
  animation:tcnAboutFloatImage 5.8s ease-in-out infinite!important;
}
.tcn-about-safe-stats{
  animation:tcnAboutStatsGlow 4.8s ease-in-out infinite!important;
}
.tcn-about-safe-feature,
.tcn-about-safe-features>div{
  transition:transform .3s ease,filter .3s ease!important;
}
.tcn-about-safe-features>div:hover{
  transform:translateX(7px)!important;
}
/* Odometer */
.tcn-odometer{
  display:flex!important;
  align-items:flex-start!important;
  justify-content:center!important;
  min-width:0!important;
  height:1em!important;
  overflow:visible!important;
  color:#ffc137!important;
  font-size:37px!important;
  line-height:1!important;
  font-weight:950!important;
  letter-spacing:-1px!important;
  white-space:nowrap!important;
}
.tcn-odo-digit{
  position:relative!important;
  display:inline-block!important;
  width:.62em!important;
  height:1em!important;
  overflow:hidden!important;
  vertical-align:top!important;
}
.tcn-odo-strip{
  display:block!important;
  width:100%!important;
  line-height:1em!important;
  text-align:center!important;
  transform:translateY(0);
  animation:tcnOdoRoll 4.8s cubic-bezier(.16,.84,.28,1) infinite!important;
  animation-delay:calc(var(--i) * .08s)!important;
  will-change:transform!important;
}
/* Số chạy từ 0 qua dãy số rồi dừng ở digit đích,
   giữ một lúc và lặp lại để khi cuộn tới vẫn nhìn thấy */
@keyframes tcnOdoRoll{
  0%{
    transform:translateY(0);
  }
  12%{
    transform:translateY(-9em);
  }
  34%,82%{
    transform:translateY(calc(var(--d) * -1em));
  }
  100%{
    transform:translateY(calc(var(--d) * -1em));
  }
}
.tcn-odo-sep,
.tcn-odo-suffix{
  display:inline-block!important;
  height:1em!important;
  line-height:1em!important;
}
.tcn-odo-sep{
  width:.28em!important;
  text-align:center!important;
}
.tcn-odo-suffix{
  margin-left:.04em!important;
}
/* Hiệu ứng section nhìn thấy rõ */
@keyframes tcnAboutFloatCopy{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(-5px)}
}
@keyframes tcnAboutFloatImage{
  0%,100%{transform:translateY(0) scale(1)}
  50%{transform:translateY(-7px) scale(1.008)}
}
@keyframes tcnAboutStatsGlow{
  0%,100%{
    transform:translateY(0);
    box-shadow:0 18px 40px rgba(5,54,119,.20)
  }
  50%{
    transform:translateY(-4px);
    box-shadow:0 24px 50px rgba(5,54,119,.30)
  }
}
.tcn-about-safe-stat em{
  animation:tcnAboutIconPulse 3.2s ease-in-out infinite!important;
}
.tcn-about-safe-stat:nth-child(2) em{animation-delay:.18s!important}
.tcn-about-safe-stat:nth-child(3) em{animation-delay:.36s!important}
.tcn-about-safe-stat:nth-child(4) em{animation-delay:.54s!important}
@keyframes tcnAboutIconPulse{
  0%,100%{transform:scale(1)}
  50%{transform:scale(1.08)}
}
@media(max-width:600px){
  .tcn-odometer{
    font-size:27px!important;
  }
}
/* V85: không tắt odometer About Us trên mobile/iOS khi Reduce Motion bật */
@media(prefers-reduced-motion:reduce) and (min-width:9999px){
  .tcn-about-safe-copy,
  .tcn-about-safe-image,
  .tcn-about-safe-stats,
  .tcn-about-safe-stat em,
  .tcn-odo-strip{
    animation:none!important;
    transform:none!important;
  }
  /* Khi giảm chuyển động, hiển thị số cuối thay vì strip */
  .tcn-odo-digit{
    overflow:visible!important;
  }
  .tcn-odo-strip{
    display:none!important;
  }
  .tcn-odometer[aria-label="10.000+"]::before{content:"10.000+"}
  .tcn-odometer[aria-label="98%"]::before{content:"98%"}
  .tcn-odometer[aria-label="20+"]::before{content:"20+"}
  .tcn-odometer[aria-label="100%"]::before{content:"100%"}
  .tcn-odometer .tcn-odo-sep,
  .tcn-odometer .tcn-odo-suffix{
    display:none!important;
  }
}
/* =========================================================
   V48 - FORCE ABOUT ANIMATION EVEN WHEN REDUCE MOTION IS ON
========================================================= */
/* Force odometer animation */
.tcn-about-safe .tcn-odo-strip{
  display:block!important;
  animation-name:tcnOdoRoll!important;
  animation-duration:4.8s!important;
  animation-timing-function:cubic-bezier(.16,.84,.28,1)!important;
  animation-iteration-count:infinite!important;
  animation-fill-mode:both!important;
}
/* Force visible section animations */
.tcn-about-safe .tcn-about-safe-copy{
  animation:tcnAboutFloatCopy 5s ease-in-out infinite!important;
}
.tcn-about-safe .tcn-about-safe-image{
  animation:tcnAboutFloatImage 5.8s ease-in-out infinite!important;
}
.tcn-about-safe .tcn-about-safe-stats{
  animation:tcnAboutStatsGlow 4.8s ease-in-out infinite!important;
}
.tcn-about-safe .tcn-about-safe-stat em{
  animation:tcnAboutIconPulse 3.2s ease-in-out infinite!important;
}
/* Override every reduce-motion rule ONLY for About Us */
@media(prefers-reduced-motion:reduce){
  .tcn-about-safe .tcn-about-safe-copy{
    animation:tcnAboutFloatCopy 5s ease-in-out infinite!important;
    transform:none;
  }
  .tcn-about-safe .tcn-about-safe-image{
    animation:tcnAboutFloatImage 5.8s ease-in-out infinite!important;
  }
  .tcn-about-safe .tcn-about-safe-stats{
    animation:tcnAboutStatsGlow 4.8s ease-in-out infinite!important;
  }
  .tcn-about-safe .tcn-about-safe-stat em{
    animation:tcnAboutIconPulse 3.2s ease-in-out infinite!important;
  }
  .tcn-about-safe .tcn-odo-digit{
    display:inline-block!important;
    position:relative!important;
    width:.62em!important;
    height:1em!important;
    overflow:hidden!important;
  }
  .tcn-about-safe .tcn-odo-strip{
    display:block!important;
    transform:translateY(0);
    animation:tcnOdoRoll 4.8s cubic-bezier(.16,.84,.28,1) infinite!important;
  }
  .tcn-about-safe .tcn-odometer::before{
    content:none!important;
    display:none!important;
  }
  .tcn-about-safe .tcn-odo-sep,
  .tcn-about-safe .tcn-odo-suffix{
    display:inline-block!important;
  }
}
/* Very obvious test animation on stats card */
@keyframes tcnAboutForcePulse{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(-6px)}
}
.tcn-about-safe .tcn-about-safe-stat{
  animation:tcnAboutForcePulse 2.8s ease-in-out infinite!important;
}
.tcn-about-safe .tcn-about-safe-stat:nth-child(2){animation-delay:.18s!important}
.tcn-about-safe .tcn-about-safe-stat:nth-child(3){animation-delay:.36s!important}
.tcn-about-safe .tcn-about-safe-stat:nth-child(4){animation-delay:.54s!important}
/* =========================================================
   V49 - STRONG ABOUT US ANIMATION
========================================================= */
/* Nội dung trái: trượt vào + nổi nhẹ */
@keyframes tcnAboutCopyStrong{
  0%{
    opacity:0;
    transform:translateX(-46px) translateY(10px);
  }
  35%{
    opacity:1;
    transform:translateX(0) translateY(0);
  }
  70%{
    transform:translateY(-5px);
  }
  100%{
    opacity:1;
    transform:translateY(0);
  }
}
.tcn-about-safe .tcn-about-safe-copy{
  opacity:1!important;
  animation:tcnAboutCopyStrong 1.25s cubic-bezier(.2,.75,.3,1) both!important;
}
/* Ảnh phải: trượt vào + zoom nhẹ */
@keyframes tcnAboutImageStrong{
  0%{
    opacity:0;
    transform:translateX(55px) scale(.94);
  }
  55%{
    opacity:1;
    transform:translateX(0) scale(1.02);
  }
  100%{
    opacity:1;
    transform:translateX(0) scale(1);
  }
}
.tcn-about-safe .tcn-about-safe-image{
  opacity:1!important;
  animation:tcnAboutImageStrong 1.35s .12s cubic-bezier(.2,.75,.3,1) both!important;
}
.tcn-about-safe .tcn-about-safe-image img{
  animation:tcnAboutImageFloat 4.2s 1.55s ease-in-out infinite!important;
}
@keyframes tcnAboutImageFloat{
  0%,100%{transform:scale(1)}
  50%{transform:scale(1.035)}
}
/* Heading */
.tcn-about-safe .tcn-about-safe-eyebrow{
  animation:tcnAboutEyebrow 1s .15s ease both!important;
}
.tcn-about-safe .tcn-about-safe-line{
  transform-origin:left center!important;
  animation:tcnAboutLine 1s .28s ease both!important;
}
.tcn-about-safe h2{
  animation:tcnAboutTitle 1.1s .35s ease both!important;
}
.tcn-about-safe h3{
  animation:tcnAboutTitle 1.1s .46s ease both!important;
}
.tcn-about-safe-copy>p{
  animation:tcnAboutTitle 1.1s .57s ease both!important;
}
@keyframes tcnAboutEyebrow{
  from{opacity:0;transform:translateY(-16px)}
  to{opacity:1;transform:none}
}
@keyframes tcnAboutLine{
  from{transform:scaleX(0);opacity:0}
  to{transform:scaleX(1);opacity:1}
}
@keyframes tcnAboutTitle{
  from{opacity:0;transform:translateY(22px)}
  to{opacity:1;transform:none}
}
/* Từng dòng lợi ích chạy lần lượt */
@keyframes tcnAboutFeatureIn{
  from{
    opacity:0;
    transform:translateX(-28px);
  }
  to{
    opacity:1;
    transform:none;
  }
}
.tcn-about-safe .tcn-about-safe-features>div{
  opacity:1!important;
  animation:tcnAboutFeatureIn .8s ease both!important;
}
.tcn-about-safe .tcn-about-safe-features>div:nth-child(1){animation-delay:.68s!important}
.tcn-about-safe .tcn-about-safe-features>div:nth-child(2){animation-delay:.84s!important}
.tcn-about-safe .tcn-about-safe-features>div:nth-child(3){animation-delay:1s!important}
.tcn-about-safe .tcn-about-safe-features>div>b{
  animation:tcnAboutFeatureIcon 2.4s 1.4s ease-in-out infinite!important;
}
.tcn-about-safe .tcn-about-safe-features>div:nth-child(2)>b{animation-delay:1.6s!important}
.tcn-about-safe .tcn-about-safe-features>div:nth-child(3)>b{animation-delay:1.8s!important}
@keyframes tcnAboutFeatureIcon{
  0%,100%{transform:translateY(0) rotate(0deg)}
  50%{transform:translateY(-6px) rotate(3deg)}
}
/* Stats container xuất hiện */
@keyframes tcnAboutStatsIn{
  from{
    opacity:0;
    transform:translateY(35px) scale(.97);
  }
  to{
    opacity:1;
    transform:none;
  }
}
.tcn-about-safe .tcn-about-safe-stats{
  opacity:1!important;
  animation:tcnAboutStatsIn 1s 1.05s ease both!important;
}
/* 4 ô thống kê nổi lần lượt */
@keyframes tcnAboutStatPop{
  0%{
    opacity:0;
    transform:translateY(24px) scale(.92);
  }
  70%{
    opacity:1;
    transform:translateY(-5px) scale(1.025);
  }
  100%{
    opacity:1;
    transform:none;
  }
}
.tcn-about-safe .tcn-about-safe-stat{
  opacity:1!important;
  animation:tcnAboutStatPop .78s ease both!important;
}
.tcn-about-safe .tcn-about-safe-stat:nth-child(1){animation-delay:1.25s!important}
.tcn-about-safe .tcn-about-safe-stat:nth-child(2){animation-delay:1.4s!important}
.tcn-about-safe .tcn-about-safe-stat:nth-child(3){animation-delay:1.55s!important}
.tcn-about-safe .tcn-about-safe-stat:nth-child(4){animation-delay:1.7s!important}
/* Sau khi xuất hiện, icon stats tiếp tục pulse nhẹ */
.tcn-about-safe .tcn-about-safe-stat em{
  animation:tcnAboutIconPulseStrong 2.4s 2.1s ease-in-out infinite!important;
}
.tcn-about-safe .tcn-about-safe-stat:nth-child(2) em{animation-delay:2.25s!important}
.tcn-about-safe .tcn-about-safe-stat:nth-child(3) em{animation-delay:2.4s!important}
.tcn-about-safe .tcn-about-safe-stat:nth-child(4) em{animation-delay:2.55s!important}
@keyframes tcnAboutIconPulseStrong{
  0%,100%{
    transform:translateY(0) scale(1);
    box-shadow:0 8px 20px rgba(0,24,64,.16);
  }
  50%{
    transform:translateY(-6px) scale(1.08);
    box-shadow:0 14px 28px rgba(0,24,64,.26);
  }
}
/* Mobile giảm cường độ nhưng vẫn thấy rõ */
@media(max-width:768px){
  .tcn-about-safe .tcn-about-safe-copy{
    animation-duration:1s!important;
  }
  .tcn-about-safe .tcn-about-safe-image{
