  }
  .tcn-about-safe .tcn-about-safe-image img{
    animation:tcnAboutImageFloat 4.2s 1.55s ease-in-out infinite!important;
  }
  .tcn-about-safe .tcn-about-safe-features>div{
    animation:tcnAboutFeatureIn .8s ease both!important;
  }
