    background:#fff!important;
    box-shadow:0 10px 27px rgba(7,63,128,.10)!important;
    transform:none!important;
  }
  /* Số thứ tự 01-06 */
  .tcn-loan-card:before{
    position:absolute!important;
    top:0!important;
    left:0!important;
