    font-weight:950!important;
    box-shadow:0 5px 12px rgba(7,63,128,.20)!important;
  }
  .tcn-loan-card:nth-child(1):before{content:"01"!important}
  .tcn-loan-card:nth-child(2):before{content:"02"!important}
  .tcn-loan-card:nth-child(3):before{content:"03"!important}
