   Tiêu đề trên giữa
   Ảnh trái + mô tả/checklist phải cùng hàng
   Button dưới giữa
   Bullet chỉ là chấm tròn xanh, không số/ký tự
========================================================= */
@media(max-width:768px){
  .tcn-loan-card{
    display:grid!important;
    grid-template-columns:40% 60%!important;
    grid-template-rows:auto 1fr auto!important;
    column-gap:0!important;
    min-height:330px!important;
    padding:0 0 20px!important;
    overflow:hidden!important;
    border-radius:25px!important;
  }
  /* Bỏ hoàn toàn số 01-06 */
  .tcn-loan-card:before{
    content:none!important;
    display:none!important;
  }
  /* Cho content tham gia grid của card để tách H3 / nội dung / button */
  .tcn-loan-content{
    display:contents!important;
  }
  /* Tiêu đề riêng một hàng phía trên, căn giữa toàn card */
  .tcn-loan-content h3{
    grid-column:1 / -1!important;
    grid-row:1!important;
    width:100%!important;
    margin:0!important;
    padding:20px 18px 17px!important;
    text-align:center!important;
    color:#073f80!important;
    font-size:31px!important;
    line-height:1.08!important;
    font-weight:950!important;
    background:#fff!important;
  }
  .tcn-loan-content h3 br{
    display:none!important;
  }
  /* Ảnh nằm bên trái cùng hàng với chú thích */
  .tcn-loan-image{
    grid-column:1!important;
    grid-row:2!important;
    align-self:stretch!important;
    width:100%!important;
    height:100%!important;
    min-height:220px!important;
    margin:0!important;
    overflow:hidden!important;
    border-radius:0 18px 18px 0!important;
  }
  .tcn-loan-image img{
    width:100%!important;
    height:100%!important;
    min-height:220px!important;
    object-fit:cover!important;
    object-position:center!important;
  }
  /* Mô tả bên phải ảnh */
  .tcn-loan-desc{
    grid-column:2!important;
    grid-row:2!important;
    align-self:start!important;
    margin:0!important;
    padding:15px 18px 8px 20px!important;
    color:#354b67!important;
