  /* Checklist cũng ở bên phải, chồng tiếp dưới mô tả */
  .tcn-loan-features{
    grid-column:2!important;
    grid-row:2!important;
    align-self:end!important;
    display:grid!important;
    gap:10px!important;
    margin:0!important;
