/* =========================================================
   V71 - SECTION 3 MOBILE: ANIMATION NÂNG CẤP
========================================================= */
@media(max-width:768px){
  /* Tiêu đề xuất hiện mềm */
  .tcn-partners-mobile-eyebrow{
    animation:tcnP3Badge 2.8s ease-in-out infinite!important;
  }
  .tcn-partners-mobile-hero h2{
    animation:tcnP3Title .9s cubic-bezier(.2,.75,.3,1) both!important;
  }
  .tcn-partners-mobile-hero i{
    transform-origin:center!important;
    animation:tcnP3Line 1.1s ease both!important;
  }
  .tcn-partners-mobile-hero p{
    animation:tcnP3Text .9s .15s ease both!important;
  }
  /* Từng nhóm trượt lên */
  .tcn-mobile-partner-group{
    animation:tcnP3GroupUp .9s cubic-bezier(.2,.75,.3,1) both!important;
  }
  .tcn-mobile-partner-group:nth-of-type(2){animation-delay:.10s!important}
  .tcn-mobile-partner-group:nth-of-type(3){animation-delay:.20s!important}
  .tcn-mobile-partner-group:nth-of-type(4){animation-delay:.30s!important}
  /* Thanh tiêu đề xanh của từng nhóm */
  .tcn-mobile-partner-group h3{
    animation:tcnP3GroupTitle 3.2s ease-in-out infinite!important;
  }
  /* Logo pop lần lượt + hover/nhịp nhẹ */
  .tcn-mobile-logo-card{
    animation:tcnP3LogoIn .75s cubic-bezier(.2,.8,.25,1) both!important;
    transition:transform .3s ease,box-shadow .3s ease!important;
  }
  .tcn-mobile-logo-card:nth-child(1){animation-delay:.05s!important}
  .tcn-mobile-logo-card:nth-child(2){animation-delay:.11s!important}
  .tcn-mobile-logo-card:nth-child(3){animation-delay:.17s!important}
  .tcn-mobile-logo-card:nth-child(4){animation-delay:.23s!important}
  .tcn-mobile-logo-card:nth-child(5){animation-delay:.29s!important}
  .tcn-mobile-logo-card:nth-child(6){animation-delay:.35s!important}
  .tcn-mobile-logo-card:nth-child(7){animation-delay:.41s!important}
  .tcn-mobile-logo-card:nth-child(8){animation-delay:.47s!important}
  .tcn-mobile-logo-card img{
    animation:tcnP3LogoFloat 4s ease-in-out infinite!important;
  }
  .tcn-mobile-logo-card:nth-child(even) img{
    animation-delay:.6s!important;
  }
  /* 3 card đối tác khác */
  .tcn-mobile-other-card{
    animation:tcnP3OtherPop .8s ease both!important;
  }
  .tcn-mobile-other-card:nth-child(1){animation-delay:.10s!important}
  .tcn-mobile-other-card:nth-child(2){animation-delay:.20s!important}
  .tcn-mobile-other-card:nth-child(3){animation-delay:.30s!important}
  .tcn-mobile-other-card b{
    animation:tcnP3IconPulse 3s ease-in-out infinite!important;
  }
  /* Khối cam kết */
  .tcn-mobile-partner-commit{
    animation:tcnP3CommitUp .95s cubic-bezier(.2,.75,.3,1) both!important;
  }
  .tcn-mobile-partner-shield{
    animation:tcnP3Shield 3s ease-in-out infinite!important;
  }
  .tcn-mobile-partner-commit li{
    animation:tcnP3CommitItem .65s ease both!important;
  }
  .tcn-mobile-partner-commit li:nth-child(1){animation-delay:.15s!important}
  .tcn-mobile-partner-commit li:nth-child(2){animation-delay:.28s!important}
  .tcn-mobile-partner-commit li:nth-child(3){animation-delay:.41s!important}
  @keyframes tcnP3Badge{
    0%,100%{transform:translateY(0);box-shadow:0 9px 20px rgba(7,63,128,.18)}
    50%{transform:translateY(-4px);box-shadow:0 14px 27px rgba(7,63,128,.27)}
  }
  @keyframes tcnP3Title{
    from{opacity:0;transform:translateY(-20px) scale(.97)}
    to{opacity:1;transform:none}
  }
  @keyframes tcnP3Line{
    from{opacity:0;transform:scaleX(0)}
    to{opacity:1;transform:scaleX(1)}
  }
  @keyframes tcnP3Text{
    from{opacity:0;transform:translateY(15px)}
    to{opacity:1;transform:none}
  }
  @keyframes tcnP3GroupUp{
    from{opacity:0;transform:translateY(34px) scale(.98)}
    to{opacity:1;transform:none}
  }
  @keyframes tcnP3GroupTitle{
    0%,100%{transform:translateY(0)}
    50%{transform:translateY(-3px)}
  }
  @keyframes tcnP3LogoIn{
    0%{opacity:0;transform:translateY(18px) scale(.90)}
    70%{opacity:1;transform:translateY(-3px) scale(1.02)}
    100%{opacity:1;transform:none}
  }
  @keyframes tcnP3LogoFloat{
    0%,100%{transform:translateY(0) scale(1)}
    50%{transform:translateY(-4px) scale(1.025)}
  }
  @keyframes tcnP3OtherPop{
    from{opacity:0;transform:translateY(20px) scale(.94)}
    to{opacity:1;transform:none}
  }
  @keyframes tcnP3IconPulse{
    0%,100%{transform:scale(1)}
    50%{transform:scale(1.08)}
  }
  @keyframes tcnP3CommitUp{
    from{opacity:0;transform:translateY(28px)}
    to{opacity:1;transform:none}
  }
  @keyframes tcnP3Shield{
    0%,100%{transform:translateY(0) scale(1)}
    50%{transform:translateY(-6px) scale(1.04)}
  }
  @keyframes tcnP3CommitItem{
    from{opacity:0;transform:translateX(18px)}
    to{opacity:1;transform:none}
  }
}
/* Tôn trọng cài đặt giảm chuyển động của thiết bị */
@media(prefers-reduced-motion:reduce){
  .tcn-partners-mobile *,
