/* =========================================================
   V76 - SECTION 2 + 3 SAFE VISIBLE ANIMATION
   Mặc định luôn hiện, tuyệt đối không ẩn bằng JS
========================================================= */
@media(max-width:768px){
  .tcn-loan-solutions,
  .tcn-loan-solutions .tcn-loan-heading,
  .tcn-loan-solutions .tcn-loan-card,
  .tcn-loan-solutions .tcn-loan-benefits,
  .tcn-partners,
  .tcn-partners-mobile,
  .tcn-partners-mobile-hero,
  .tcn-mobile-partner-group,
  .tcn-mobile-partner-commit{
    opacity:1!important;
    visibility:visible!important;
  }
  .tcn-finance-text-logo{
    min-height:106px!important;
    display:flex!important;
    flex-direction:column!important;
    align-items:center!important;
    justify-content:center!important;
    gap:5px!important;
    background:linear-gradient(145deg,#fff,#eef7ff)!important;
  }
  .tcn-finance-text-logo strong{
    color:#073f80!important;
    font-size:25px!important;
    line-height:1!important;
    font-weight:950!important;
  }
  .tcn-finance-text-logo span{
    color:#0b67d5!important;
    font-size:15px!important;
    line-height:1!important;
    font-weight:850!important;
  }
  /* Animation nhẹ luôn chạy */
  .tcn-loan-image img{
    animation:tcnLoanImageFloat 5s ease-in-out infinite!important;
  }
  .tcn-loan-btn{
    animation:tcnLoanBtnPulse 3s ease-in-out infinite!important;
  }
  .tcn-mobile-logo-card img,
  .tcn-finance-text-logo{
    animation:tcnP3LogoFloat 4s ease-in-out infinite!important;
  }
  /* Scroll-driven animation nếu trình duyệt hỗ trợ.
     Không hỗ trợ thì section vẫn hiện bình thường. */
  @supports (animation-timeline:view()){
    .tcn-loan-heading{
      animation:v76Head linear both!important;
      animation-timeline:view()!important;
      animation-range:entry 5% cover 30%!important;
    }
    .tcn-loan-card:nth-child(odd){
      animation:v76Left linear both!important;
      animation-timeline:view()!important;
      animation-range:entry 2% cover 30%!important;
    }
    .tcn-loan-card:nth-child(even){
      animation:v76Right linear both!important;
      animation-timeline:view()!important;
      animation-range:entry 2% cover 30%!important;
    }
    .tcn-loan-benefits{
      animation:v76Up linear both!important;
      animation-timeline:view()!important;
      animation-range:entry 2% cover 30%!important;
    }
    .tcn-partners-mobile-hero{
      animation:v76Head linear both!important;
      animation-timeline:view()!important;
      animation-range:entry 5% cover 30%!important;
    }
    .tcn-mobile-partner-group:nth-of-type(odd){
      animation:v76Left linear both!important;
      animation-timeline:view()!important;
      animation-range:entry 2% cover 30%!important;
    }
    .tcn-mobile-partner-group:nth-of-type(even){
      animation:v76Right linear both!important;
      animation-timeline:view()!important;
      animation-range:entry 2% cover 30%!important;
    }
    .tcn-mobile-partner-commit{
      animation:v76Up linear both!important;
      animation-timeline:view()!important;
      animation-range:entry 2% cover 30%!important;
    }
  }
  @keyframes v76Head{
