/* =========================================================
   V85 - FIX ABOUT US ODOMETER ON MOBILE / IOS SAFARI
========================================================= */
@-webkit-keyframes tcnOdoRollMobile{
  0%{-webkit-transform:translate3d(0,0,0);transform:translate3d(0,0,0)}
  18%{-webkit-transform:translate3d(0,-9em,0);transform:translate3d(0,-9em,0)}
  42%,86%,100%{-webkit-transform:translate3d(0,calc(var(--d) * -1em),0);transform:translate3d(0,calc(var(--d) * -1em),0)}
}
@keyframes tcnOdoRollMobile{
  0%{-webkit-transform:translate3d(0,0,0);transform:translate3d(0,0,0)}
  18%{-webkit-transform:translate3d(0,-9em,0);transform:translate3d(0,-9em,0)}
  42%,86%,100%{-webkit-transform:translate3d(0,calc(var(--d) * -1em),0);transform:translate3d(0,calc(var(--d) * -1em),0)}
}
@media(max-width:900px){
  .tcn-about-safe .tcn-odometer{
    display:flex!important;overflow:visible!important;
  }
  .tcn-about-safe .tcn-odo-digit{
    display:inline-block!important;position:relative!important;
    width:.62em!important;height:1em!important;overflow:hidden!important;
    -webkit-transform:translateZ(0);transform:translateZ(0);
  }
  .tcn-about-safe .tcn-odo-strip{
    display:block!important;
    -webkit-animation:tcnOdoRollMobile 4.8s cubic-bezier(.16,.84,.28,1) infinite!important;
    animation:tcnOdoRollMobile 4.8s cubic-bezier(.16,.84,.28,1) infinite!important;
    -webkit-animation-delay:calc(var(--i) * .08s)!important;
    animation-delay:calc(var(--i) * .08s)!important;
    -webkit-animation-fill-mode:both!important;animation-fill-mode:both!important;
    -webkit-backface-visibility:hidden!important;backface-visibility:hidden!important;
    will-change:transform!important;
  }
  .tcn-about-safe .tcn-odometer::before{content:none!important;display:none!important}
  .tcn-about-safe .tcn-odo-sep,.tcn-about-safe .tcn-odo-suffix{display:inline-block!important}
}
@media(prefers-reduced-motion:reduce) and (max-width:900px){
  .tcn-about-safe .tcn-odo-strip{
    display:block!important;
    -webkit-animation:tcnOdoRollMobile 4.8s cubic-bezier(.16,.84,.28,1) infinite!important;
    animation:tcnOdoRollMobile 4.8s cubic-bezier(.16,.84,.28,1) infinite!important;
  }
  .tcn-about-safe .tcn-odo-digit{overflow:hidden!important}
}
/* === V88 FAQ NATIVE DETAILS FIX - NO JAVASCRIPT REQUIRED === */
.tcn-faq details.tcn-faq-item{display:block!important}
.tcn-faq summary.tcn-faq-question{list-style:none!important;-webkit-appearance:none;appearance:none}
