/* v102 - Footer social: chỉ Zalo + điện thoại */
.tcn-footer-social{
  display:flex;
  gap:10px;
  align-items:center;
}
.tcn-footer-social a{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-width:42px;
  height:42px;
  padding:0 12px;
  border-radius:999px;
  background:#0d57b5;
  border:1px solid #347edb;
  color:#fff!important;
  font-weight:900;
  font-size:14px;
}
.tcn-footer-social a:first-child{
  background:#1489f3;
}
/* v103 - Căn giữa icon Zalo + điện thoại trong vòng tròn */
.tcn-footer-social{
  display:flex!important;
  align-items:center!important;
  gap:10px!important;
}
.tcn-footer-social a{
  width:44px!important;
  min-width:44px!important;
  height:44px!important;
  padding:0!important;
  display:grid!important;
  place-items:center!important;
  border-radius:50%!important;
  line-height:1!important;
  text-align:center!important;
  vertical-align:middle!important;
  font-size:15px!important;
  font-weight:900!important;
  overflow:hidden!important;
}
.tcn-footer-social a:first-child{
  font-size:11px!important;
  letter-spacing:-.2px!important;
}
.tcn-footer-social a:last-child{
  font-size:20px!important;
  font-family:Arial,Helvetica,sans-serif!important;
}
.tcn-footer-social a > *{
  margin:0!important;
  padding:0!important;
  line-height:1!important;
  transform:none!important;
}
/* v109 - Force Section 1 banner replacement */
.hero{
  background-image:none!important;
}
.hero-bg{
  display:block!important;
  opacity:1!important;
  visibility:visible!important;
  filter:none!important;
  content:normal!important;
}
/* v117 - ABOUT IMAGE HARD REPLACE */
#about .tcn-about-safe-image-v117{
  position:relative!important;
  overflow:hidden!important;
  min-height:480px!important;
  background:#eaf4ff!important;
}
#about #tcn-about-team-v117{
  display:block!important;
  width:100%!important;
  height:100%!important;
  min-height:480px!important;
  max-width:none!important;
  object-fit:cover!important;
  object-position:center center!important;
  opacity:1!important;
  visibility:visible!important;
  filter:none!important;
}
@media(max-width:700px){
  #about .tcn-about-safe-image-v117,
  #about #tcn-about-team-v117{
    min-height:330px!important;
  }
}
/* ==========================================================
   TIN TUC BLOGGER - MASTER SAFE
   Home: landing page | Index/Label: 3/2/1 columns | Item: detail
   ========================================================== */
#main{
  display:block!important;height:auto!important;min-height:0!important;overflow:visible!important;
  width:min(1180px,calc(100% - 36px))!important;margin:0 auto!important;padding:54px 0 72px!important;border:0!important;
}
#main > .widget{display:none!important}
#main > #Blog1,#Blog1{display:block!important;height:auto!important;overflow:visible!important}
#Blog1 .widget-content{display:block!important}
/* Index / label / archive */
.tcn-page-index #Blog1 .blog-posts{
  display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:26px!important;
}
.tcn-page-index #Blog1 .date-outer,.tcn-page-index #Blog1 .date-posts{display:contents!important}
.tcn-page-index #Blog1 .date-header{display:none!important}
.tcn-page-index #Blog1 .post-outer{
  display:block!important;margin:0!important;padding:0!important;background:#fff!important;border:1px solid #e5eaf1!important;
  border-radius:16px!important;overflow:hidden!important;box-shadow:0 10px 28px rgba(9,53,102,.08)!important;
}
.tcn-page-index #Blog1 .post{margin:0!important;padding:0!important}
.tcn-page-index #Blog1 .post-title{margin:0!important;padding:20px 22px 10px!important;font-size:21px!important;line-height:1.35!important;font-weight:800!important}
.tcn-page-index #Blog1 .post-title a{color:#172033!important;text-decoration:none!important}
.tcn-page-index #Blog1 .post-title a:hover{color:#0b5bb5!important}
.tcn-page-index #Blog1 .post-body{padding:0 22px 22px!important;color:#667085!important;font-size:15px!important;line-height:1.7!important}
.tcn-page-index #Blog1 .post-body img{width:100%!important;height:auto!important;border-radius:10px!important}
.tcn-page-index #Blog1 .post-footer{padding:0 22px 20px!important;color:#667085!important;font-size:13px!important}
.tcn-page-index #Blog1 .jump-link{padding:0 22px 22px!important}
.tcn-page-index #Blog1 .jump-link a{display:inline-flex!important;align-items:center!important;min-height:42px!important;padding:0 18px!important;border-radius:8px!important;background:#0b5bb5!important;color:#fff!important;font-weight:800!important}
.tcn-page-index #Blog1 .status-msg-wrap{display:block!important;grid-column:1/-1!important;margin:0 0 10px!important}
.tcn-page-index #Blog1 .blog-pager{grid-column:1/-1!important;margin:38px 0 0!important;text-align:center!important}
/* Single article / static page */
.tcn-page-item #main,.tcn-page-static_page #main{width:min(980px,calc(100% - 36px))!important;padding-top:48px!important}
.tcn-page-item #Blog1 .blog-posts,.tcn-page-static_page #Blog1 .blog-posts{display:block!important}
.tcn-page-item #Blog1 .date-header,.tcn-page-static_page #Blog1 .date-header{display:none!important}
.tcn-page-item #Blog1 .post-outer,.tcn-page-static_page #Blog1 .post-outer{display:block!important;margin:0!important;padding:0!important}
.tcn-page-item #Blog1 .post,.tcn-page-static_page #Blog1 .post{margin:0!important;padding:0!important}
.tcn-page-item #Blog1 .post-title,.tcn-page-static_page #Blog1 .post-title{margin:0 0 16px!important;padding:0!important;color:#172033!important;font-size:clamp(32px,4vw,48px)!important;line-height:1.16!important;font-weight:900!important}
.tcn-page-item #Blog1 .post-body,.tcn-page-static_page #Blog1 .post-body{padding:0!important;color:#344054!important;font-size:18px!important;line-height:1.82!important}
.tcn-page-item #Blog1 .post-body h2,.tcn-page-static_page #Blog1 .post-body h2{margin:38px 0 14px!important;color:#123a8f!important;font-size:30px!important;line-height:1.3!important}
.tcn-page-item #Blog1 .post-body h3,.tcn-page-static_page #Blog1 .post-body h3{margin:30px 0 12px!important;color:#172033!important;font-size:24px!important;line-height:1.35!important}
.tcn-page-item #Blog1 .post-body img,.tcn-page-static_page #Blog1 .post-body img{display:block!important;max-width:100%!important;height:auto!important;margin:24px auto!important;border-radius:14px!important}
.tcn-page-item #Blog1 .post-body blockquote,.tcn-page-static_page #Blog1 .post-body blockquote{margin:28px 0!important;padding:20px 24px!important;border-left:4px solid #f59e0b!important;background:#f4f8fd!important;border-radius:0 12px 12px 0!important}
.tcn-page-item #Blog1 .post-footer,.tcn-page-static_page #Blog1 .post-footer{margin-top:34px!important;padding-top:22px!important;border-top:1px solid #e5eaf1!important;color:#667085!important}
@media(max-width:980px){
  .tcn-page-index #Blog1 .blog-posts{grid-template-columns:repeat(2,minmax(0,1fr))!important}
}
@media(max-width:680px){
  #main{width:calc(100% - 28px)!important;padding:34px 0 52px!important}
  .tcn-page-index #Blog1 .blog-posts{grid-template-columns:1fr!important;gap:20px!important}
  .tcn-page-index #Blog1 .post-title{font-size:19px!important;padding:18px 18px 9px!important}
  .tcn-page-index #Blog1 .post-body{padding:0 18px 18px!important}
  .tcn-page-item #Blog1 .post-title,.tcn-page-static_page #Blog1 .post-title{font-size:32px!important}
  .tcn-page-item #Blog1 .post-body,.tcn-page-static_page #Blog1 .post-body{font-size:17px!important;line-height:1.75!important}
  .tcn-page-item #Blog1 .post-body h2,.tcn-page-static_page #Blog1 .post-body h2{font-size:26px!important}
}


