b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;
// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }
      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }
      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };
      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };
      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;
      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };
      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }
      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };
      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };
      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
(function(){
  function initV79SectionSlide(){
    if(window.innerWidth > 768){ return; }
    var s2=document.querySelector('.tcn-loan-solutions');
    var s3=document.querySelector('.tcn-partners');
    var items=[
      {el:s2,dir:'left',done:false},
      {el:s3,dir:'right',done:false}
    ];
    function play(item){
      if(!item.el || item.done){ return; }
      item.done=true;
      var fromX = item.dir==='left' ? -140 : 140;
      if(item.el.animate){
        item.el.animate(
          [
            {
              opacity:0.15,
              transform:'translate3d('+fromX+'px,0,0)'
            },
            {
              opacity:1,
              transform:'translate3d(0,0,0)'
            }
          ],
          {
            duration:1100,
            easing:'cubic-bezier(.16,.84,.28,1)',
            fill:'both'
          }
        );
      }else{
        item.el.style.opacity='1';
        item.el.style.transform='none';
      }
    }
    function check(){
      var vh=window.innerHeight || document.documentElement.clientHeight || 700;
      for(var i=0;i<items.length;i++){
        var item=items[i];
        if(!item.el || item.done){ continue; }
        var r=item.el.getBoundingClientRect();
        /*
          Chỉ chạy khi đầu section đi vào khoảng 82% viewport.
          Nghĩa là bạn phải thật sự kéo tới section mới bắt đầu trượt.
        */
        if(r.top < vh*0.82 && r.bottom > 0){
          play(item);
        }
      }
    }
    window.addEventListener('scroll',check,{passive:true});
    window.addEventListener('touchmove',check,{passive:true});
    window.addEventListener('resize',check,false);
    window.setTimeout(check,600);
    /* Blogger/iOS fallback */
    var watcher=window.setInterval(function(){
      check();
      var allDone=true;
      for(var j=0;j<items.length;j++){
        if(items[j].el && !items[j].done){
          allDone=false;
          break;
        }
      }
      if(allDone){
        window.clearInterval(watcher);
      }
    },250);
  }
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',initV79SectionSlide);
  }else{
    initV79SectionSlide();
  }
})();

(function(){
  function init(){
    var form=document.getElementById('tcn-email-consult-form');
    if(!form) return;
    var map={name:'Vui lòng nhập họ và tên.',phone:'Vui lòng nhập số điện thoại.',loan_type:'Vui lòng chọn dịch vụ quan tâm.'};
    function box(n){return form.querySelector('[data-error-for="'+n+'"]');}
    function field(n){return form.querySelector('[name="'+n+'"]');}
    function paint(n,msg){var e=field(n),b=box(n);if(e){var h=e.closest('.tcn-field')||e;h.style.setProperty('border','2px solid #d92d20','important');h.style.setProperty('background','#fff5f4','important');}if(b){b.textContent=msg;b.style.setProperty('display','block','important');b.style.setProperty('color','#d92d20','important');}}
    function clear(n){var e=field(n),b=box(n);if(e){var h=e.closest('.tcn-field')||e;h.style.removeProperty('border');h.style.removeProperty('background');}if(b){b.textContent='';b.style.setProperty('display','none','important');}}
    function valid(){
      var ok=true,n=field('name'),p=field('phone'),em=field('email'),l=field('loan_type'),c=form.querySelector('.tcn-consent input[type="checkbox"]');
      if(!n||n.value.trim().length<2){paint('name',map.name);ok=false}else clear('name');
      var pv=p?p.value.trim().replace(/\s+/g,''):'';if(!/^(0|\+84)[0-9]{9,10}$/.test(pv)){paint('phone',pv?'Số điện thoại chưa đúng định dạng.':map.phone);ok=false}else clear('phone');
      var ev=em?em.value.trim():'';if(ev&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(ev)){paint('email','Email chưa đúng định dạng.');ok=false}else clear('email');
      if(!l||!l.value){paint('loan_type',map.loan_type);ok=false}else clear('loan_type');
      var cb=box('consent');if(c&&!c.checked){if(cb){cb.textContent='Vui lòng xác nhận đồng ý trước khi gửi.';cb.style.setProperty('display','block','important');cb.style.setProperty('color','#d92d20','important');}ok=false}else if(cb){cb.textContent='';cb.style.setProperty('display','none','important');}
      return ok;
    }
    form.addEventListener('submit',function(e){if(!valid()){e.preventDefault();window.tcnFormWasSubmitted=false;var s=document.getElementById('tcn-form-status');if(s){s.style.display='block';s.style.background='#fff1f0';s.style.color='#b42318';s.textContent='Vui lòng kiểm tra các trường được báo đỏ bên dưới.';}}});
    ['name','phone','email'].forEach(function(n){var e=field(n);if(e)e.addEventListener('input',function(){valid();});});
    var l=field('loan_type');if(l)l.addEventListener('change',valid);
    var c=form.querySelector('.tcn-consent input[type="checkbox"]');if(c)c.addEventListener('change',valid);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();

