(function(){
  function txt(el){return el?el.textContent.trim():'';}
  function run(){
    var path=location.pathname;
    var isList=path.indexOf('/search/label/')===0 || path==='/search';
    var isArticle=/\/\d{4}\/\d{2}\/.+\.html$/.test(path);
    if(!isList && !isArticle) return;
    document.body.classList.add(isList?'tcn-news-list':'tcn-news-article');
    if(isList){
      var main=document.getElementById('main'); if(!main) return;
      if(!document.querySelector('.tcn-news-hero')){
        var hero=document.createElement('section');hero.className='tcn-news-hero';
        hero.innerHTML='<div class="tcn-news-hero-inner"><h1>Tin tức</h1><p>Cập nhật kiến thức tài chính, kinh nghiệm vay vốn và thông tin thị trường mới nhất</p></div>';
        main.parentNode.insertBefore(hero,main);
        var bc=document.createElement('div');bc.className='tcn-news-breadcrumb';bc.innerHTML='<a href="/">Trang chủ</a> &nbsp;›&nbsp; <strong>Tin tức</strong>';main.parentNode.insertBefore(bc,main);
        var cats=document.createElement('nav');cats.className='tcn-news-cats';cats.innerHTML='<a class="active" href="/search/label/tin-tuc">Tất cả</a><a href="/search/label/kien-thuc-tai-chinh">Kiến thức tài chính</a><a href="/search/label/kinh-nghiem-vay-von">Kinh nghiệm vay vốn</a><a href="/search/label/so-sanh-danh-gia">So sánh &amp; đánh giá</a><a href="/search/label/tin-thi-truong">Tin thị trường</a><a href="/search/label/huong-dan-thu-tuc">Hướng dẫn thủ tục</a>';main.parentNode.insertBefore(cats,main);
      }
      document.querySelectorAll('#Blog1 .post').forEach(function(post){
        if(post.dataset.tcnCard) return; post.dataset.tcnCard='1';
        var body=post.querySelector('.post-body'); var title=post.querySelector('.post-title'); if(!title) return;
        var link=title.querySelector('a'); var img=body?body.querySelector('img'):null;
        var src=img?(img.getAttribute('src')||img.getAttribute('data-original-src')||''):'';
        var label=post.querySelector('.post-labels a'); var time=post.querySelector('.timestamp-link,.published,.post-timestamp');
        var image=document.createElement('img');image.className='tcn-card-image';image.alt=txt(title);image.loading='lazy';
        image.src=src||'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhiX7DZHHug-2borfUxw4fPP0EOIcVb-WvpQIdEHIEO77sFetUPpEy2sTiT52egGYJmBHNKC3d2Bxiu1vGVmzReLwfuEEL1xEh2ENYlLKyWl2jOHauEYZRym-P2YKhopzLgy8fFlZ_tyuNinc2brUY636P7DPIoU5Ca7VIQAVnd_kw3vW31biGhw89T7WSH/s0/banner-tai-chinh-nhanh.webp';
        if(link){var a=document.createElement('a');a.href=link.href;a.appendChild(image);post.insertBefore(a,post.firstChild)}else post.insertBefore(image,post.firstChild);
        var inner=document.createElement('div');inner.className='tcn-card-inner';
        if(label){var badge=document.createElement('span');badge.className='tcn-card-label';badge.textContent=txt(label);inner.appendChild(badge)}
        inner.appendChild(title);
        if(body) inner.appendChild(body);
        var meta=document.createElement('div');meta.className='tcn-card-meta';meta.innerHTML='<span>'+((time&&txt(time))||'Tin mới')+'</span>'+(link?'<a class="tcn-card-read" href="'+link.href+'">Đọc thêm →</a>':'');inner.appendChild(meta);
        post.appendChild(inner);
      });
    }
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run();
})();
